window.EXPOSANTS=[{"name": "AB Câble", "description": {"fr": "Description à venir.", "en": "Description coming soon."}, "logo": "assets/logos/exposant-1.png", "website": "https://abcable.ca/", "id": "exposant-1"}, {"name": "ABB Électrification", "description": {"fr": "ABB Électrification est un chef de file mondial en matière de distribution d'électricité efficace et fiable. Notre division Produits d'installation conçoit et fabrique des solutions pour des applications résidentielles, commerciales, industrielles et de services publics. Avec 80 % de notre portefeuille fabriqué ou assemblé au Canada, nous utilisons des matériaux locaux pour produire des marques de confiance telles que IBERVILLE®, Microlectric® et Star Teck®. tnb.ca.abb.com", "en": "ABB Electrification is a global leader in efficient, reliable electricity distribution. Our Installation Products division designs and manufactures solutions for residential, commercial, industrial and utility applications. With 80% of our portfolio manufactured or assembled in Canada, we use local materials to produce trusted brands such as IBERVILLE®, Microlectric® and Star Teck®. tnb.ca.abb.com"}, "logo": "assets/logos/exposant-2.png", "website": "https://new.abb.com/ca/fr/a-propos-dabb/nos-secteurs-d'affaires/electrification", "id": "exposant-2"}, {"name": "Accès Industriel", "description": {"fr": "Chez Accès Industriel, nous allons bien au-delà de la fabrication de Toyota Land Cruiser sur mesure pour le secteur minier. Que ce soit pour acheter, louer, reconditionner, entretenir ou réparer un équipement minier, industriel ou de construction, nous sommes là pour vous soutenir à chaque étape. Nous offrons également des pièces et composantes pour tout type d’équipement en plus d’accessoires et d’équipements de levage et d’arrimage. Besoin de renfort? Profitez de nos services de location de personnel qualifié. Pour tous en savoir plus sur l’ensemble de nos produits et services : www.acces-s.ca", "en": "At Accès Industriel, we go well beyond building custom Toyota Land Cruisers for the mining sector. Whether you need to buy, rent, refurbish, maintain or repair mining, industrial or construction equipment, we are here to support you every step of the way. We also offer parts and components for all types of equipment, along with lifting and load-securing accessories and equipment. Need extra help? Take advantage of our skilled personnel rental services. To learn more about all our products and services: www.acces-s.ca"}, "logo": "assets/logos/exposant-3.png", "website": "https://acces-s.ca/", "id": "exposant-3"}, {"name": "Adria Power System", "description": {"fr": "Avec plus de 25 ans d'expérience dans la conception et la fabrication de produits de distribution et de puissance électrique dans les secteurs industriels, commerciaux et miniers, Adria Power Systems® est un chef de file pour lequel sa fidèle clientèle accorde son entière confiance dans la mise en place des meilleures solutions possibles, adaptées à leur propre situation. Adria est composée d’une équipe professionnelle et dynamique supervisée par des gens d’expériences et visionnaires.L'entreprise a développé une expertise répondant aux standards de robustesse, de fiabilité et de sécurité accrue tout en utilisant les plus récentes technologies en développement. La communication avec nos clients et l'expertise, font d’Adria, depuis ses débuts, un fournisseur d’équipements de haute qualité, durables, sécuritaires et performants.", "en": "With more than 25 years of experience designing and manufacturing electrical distribution and power products for the industrial, commercial and mining sectors, Adria Power Systems® is a leader whose loyal customers place their full trust in its ability to implement the best possible solutions for their specific situations. Adria consists of a professional, dynamic team led by experienced, forward-thinking people. The company has developed expertise that meets demanding standards for ruggedness, reliability and enhanced safety while using the latest emerging technologies. Since its beginnings, communication with customers and technical expertise have made Adria a supplier of high-quality, durable, safe and high-performance equipment."}, "logo": "assets/logos/exposant-4.png", "website": "https://adria-corp.com/fr/", "id": "exposant-4"}, {"name": "Agence BTA", "description": {"fr": "Manufacturier spécialisé dans la fabrication sur mesure de système de câble omnibus (cable bus) à basse et moyenne tension, boitier sur mesure, boitier de répartition, boitier de type « camlock » . Agence BTA est un agent manufacturier de premier plan au Québec, offrant des produits de distribution et de transport d’énergie électrique provenant de fabricants reconnus dans notre industrie.Rex Power Magnetics / Agence BTA : Rex Power Magnetics se spécialise dans la conception et la fabrication de transformateurs de puissance, résine moulée (cast coil), de distribution, charge non linéaire et de mise à la terre. LED in Action / Agence BTA : Fabricant d'appareils d'éclairage industriel au DEL adaptés aux environnements difficiles.", "en": "A manufacturer specializing in custom low- and medium-voltage cable bus systems, custom enclosures, distribution enclosures and camlock enclosures. Agence BTA is a leading manufacturers’ representative in Québec, offering electrical power distribution and transmission products from recognized manufacturers in our industry.\n\nRex Power Magnetics / Agence BTA: Rex Power Magnetics specializes in the design and manufacture of power, cast-coil, distribution, nonlinear-load and grounding transformers.\n\nLED in Action / Agence BTA: A manufacturer of industrial LED lighting fixtures designed for harsh environments."}, "logo": "assets/logos/exposant-5.png", "website": "https://agencebta.com/system/", "id": "exposant-5"}, {"name": "AmNor Industries", "description": {"fr": "AmNor Industries est une entreprise spécialisée en nettoyage industriel ainsi qu’en gestion, transport et récupération de matière dangereuse résiduelle (M.D.R.). L’équipe de gestion qui compose AmNor Industries est une équipe d’expérience œuvrant dans ce secteur depuis plus de 30 ans. Les gestionnaires connaissent les besoins de la clientèle à qui ils offrent leurs services et ont un souci irréprochable du service qui est offert. La santé et la sécurité font partie intégrante des valeurs de l’entreprise. Ainsi, l’entreprise cherche continuellement à innover dans le domaine afin d’améliorer ses façons de faire afin de protéger ses travailleurs, contractants et les travailleurs des entreprises pour qui ils opèrent.", "en": "AmNor Industries specializes in industrial cleaning and the management, transportation and recovery of hazardous residual materials. Its experienced management team has worked in this sector for more than 30 years. Managers understand their customers’ needs and are deeply committed to the quality of the service they provide. Health and safety are integral to the company’s values. AmNor therefore continually seeks to innovate and improve its working methods to protect its employees, contractors and the employees of the companies it serves."}, "logo": "assets/logos/exposant-6.png", "website": "https://www.amnorindustries.com/", "id": "exposant-6"}, {"name": "ASDR Canada Inc.", "description": {"fr": "ASDR est une entreprise fournissant des solutions spécialisées au secteur minier, forestier, industriel et municipal. Nous avons pour mission de réaliser les projets de nos clients avec passion, résilience et innovation. Depuis 2006, nous avons bâti une solide réputation dans le marché, notamment avec notre capacité à livrer des projets clé en main. Notre large gamme de services se regroupe en quatre pôles d’excellence : Gestion de projet et Ingénierie, Traitement des eaux, Fabrication et Services industriels. Nous développons aussi des technologies innovatrices de traitement des eaux et de déshydratation des boues. Nos solutions couvrent le cycle de vie complet d’un projet : des essais en laboratoire et pilotes, jusqu’à la fabrication, la mise en service, l’opération et la maintenance.", "en": "ASDR provides specialized solutions for the mining, forestry, industrial and municipal sectors. Our mission is to deliver our customers’ projects with passion, resilience and innovation. Since 2006, we have built a strong market reputation, particularly through our ability to deliver turnkey projects. Our broad range of services is organized into four centres of excellence: Project Management and Engineering, Water Treatment, Manufacturing and Industrial Services. We also develop innovative water-treatment and sludge-dewatering technologies. Our solutions cover the entire project life cycle, from laboratory and pilot testing through manufacturing, commissioning, operation and maintenance."}, "logo": "assets/logos/exposant-7.png", "website": "https://asdr.ca/", "id": "exposant-7"}, {"name": "Bradycorp", "description": {"fr": "Brady est un fabricant de solutions complètes qui identifient et protègent les individus, les produits et les lieux. Les produits de Brady aident les clients à améliorer la sécurité, la productivité et les performances et comprennent des étiquettes, des enseignes, des dispositifs de sécurité, des systèmes d'impression et des logiciels de haute performance.", "en": "Brady manufactures comprehensive solutions that identify and protect people, products and places. Brady’s products help customers improve safety, productivity and performance, and include labels, signs, safety devices, high-performance printing systems and software."}, "logo": "assets/logos/exposant-8.png", "website": "https://www.bradycanada.ca/", "id": "exposant-8"}, {"name": "Bucan", "description": {"fr": "Des produits fiables, sûrs, efficaces et conçus pour les applications robustes et exigeantes. Produits de chauffage de procédés industriels. Spécialistes innovateurs en chauffage industriel.", "en": "Reliable, safe and efficient products designed for rugged, demanding applications. Industrial process-heating products. Innovative specialists in industrial heating."}, "logo": "assets/logos/exposant-9.png", "website": "https://www.bucan.com/", "id": "exposant-9"}, {"id": "exposant-canshield", "name": "CanShield", "description": {"fr": "Description à venir.", "en": "Description coming soon."}, "logo": "assets/logos/exposant-canshield.png", "website": "https://www.canshieldrockbolts.com/"}, {"name": "Centre de peinture LBG", "description": {"fr": "Le Centre de peinture LBG se spécialise dans la vente de produits et d’équipements de peinture industrielle, commerciale et résidentielle. Indissociable à la vente de nos produits, nous excellons dans le service à la clientèle par un soutien technique complet : de la planification d’un projet, en passant par sa réalisation jusqu’à son entretien. En plus de notre expérience et nos connaissances acquises depuis près de 50 ans, nos services sont appuyés par un inspecteur NACE CIP 1 qui est également Ceinture Noire de l’approche d’optimisation LEAN SIX-SIGMA. Les secteurs miniers et forestiers font partie de nos principaux domaines de spécialisation.", "en": "Centre de peinture LBG specializes in selling industrial, commercial and residential paint products and equipment. Our product sales are backed by excellent customer service and comprehensive technical support, from project planning through completion and maintenance. In addition to the experience and knowledge we have gained over nearly 50 years, our services are supported by a NACE CIP 1 inspector who also holds a LEAN SIX SIGMA Black Belt in process optimization. The mining and forestry sectors are among our main areas of specialization."}, "logo": "assets/logos/exposant-10.png", "website": "https://www.cplbg.com/", "id": "exposant-10"}, {"name": "Channell", "description": {"fr": "Channell Commercial Canada est un fabricant et fournisseur de solutions de fibre optique de classe mondiale, de piédestaux en thermoplastique et de voûtes souterraines, répondant à tous vos besoins en matière de construction de réseaux extérieurs. Spécialisés dans les réseaux de fibre optique complets, nous sommes à la fine pointe de l’innovation dans le secteur depuis plus de 90 ans. Nous continuons à faire évoluer nos produits afin de répondre aux besoins et aux exigences croissantes de la construction de réseaux de communication extérieurs", "en": "Channell Commercial Canada is a world-class manufacturer and supplier of fibre-optic solutions, thermoplastic pedestals and underground vaults, meeting all your outside-plant network construction needs. Specializing in complete fibre-optic networks, we have been at the forefront of industry innovation for more than 90 years. We continue to develop our products to meet the growing needs and requirements of outside-plant communications network construction."}, "logo": "assets/logos/exposant-11.png", "website": "https://www.channell.com/", "id": "exposant-11"}, {"name": "Comairco", "description": {"fr": "LA SOLUTION EN AIR COMPRIMÉ… VENTE (NEUF OU USAGÉ), LOCATION, SERVICE 24H, RÉPARATION BLOCS COMPRESSEURS, INSTALLATION. Depuis 50 ans, COMAIRCO offre son expertise en matière de compresseurs d'air et d'équipements d'air comprimé. 1er partenaire exclusif de la marque Sullair, 24 succursales au Canada et aux Etats-Unis et une équipe de 85 techniciens certifiés, Comairco se distingue par son efficacité devant toute compétition. Le service clientèle, le respect et l'excellence sont les bases du succès de Comairco, car nous faisons de votre priorité notre priorité! Communiquez dès aujourd'hui avec notre équipe en composant le 1 800 463-8780 afin d'en savoir davantage sur nos produits ou pour bénéficier de nos services techniques disponibles 24 heures sur 24, 7 jours sur 7.", "en": "YOUR COMPRESSED-AIR SOLUTION… SALES (NEW OR USED), RENTALS, 24-HOUR SERVICE, COMPRESSOR AIR-END REPAIRS AND INSTALLATION. For 50 years, COMAIRCO has provided expertise in air compressors and compressed-air equipment. As Sullair’s first exclusive partner, with 24 branches in Canada and the United States and a team of 85 certified technicians, Comairco stands out for its efficiency in a competitive market. Customer service, respect and excellence are the foundations of Comairco’s success: we make your priority our priority! Contact our team today at 1 800 463-8780 to learn more about our products or to access our technical services, available 24 hours a day, 7 days a week."}, "logo": "assets/logos/exposant-12.png", "website": "https://comairco.com/fr/", "id": "exposant-12"}, {"name": "Creighton Rock Drill Ltd", "description": {"fr": "Est une compagnie qui se spécialise dans les produits d’attaque au sol et de forage. Nous avons un très grand inventaire en attaque au sol avec les produits Black Cat, MTG, Combi, Hensley, Olosfors et autres. Creighton est une compagnie familiale en affaires depuis plus de 50 ans!", "en": "A company specializing in ground-engaging tools and drilling products. We maintain a very large inventory of ground-engaging products from Black Cat, MTG, Combi, Hensley, Olosfors and other brands. Creighton is a family-owned company that has been in business for more than 50 years!"}, "logo": "assets/logos/exposant-13.png", "website": "https://www.crdcreighton.com/", "id": "exposant-13"}, {"name": "CSM Distribution Canada inc / JMPE", "description": {"fr": "Services de réparations et fabrications de boyaux hydrauliques, de réparation de valve, de pompe et de moteur hydraulique, d’usinage conventionnel et numérique, de soudure et de réparation de cylindre et d’un représentant pour gestion de stock et location de presse.", "en": "Hydraulic hose repair and fabrication; valve, pump and hydraulic motor repair; conventional and CNC machining; welding and cylinder repair; inventory management support from a representative; and crimping press rentals."}, "logo": "assets/logos/exposant-14.png", "website": "https://csmdistribution.com/", "id": "exposant-14"}, {"name": "Distribution Sogitex", "description": {"fr": "Sogitex est une entreprise comprenant 250 employés à travers l’Abitibi-Témiscamingue. Notre but est de vous accompagner avec un service complet. Nous sommes distributeur de produits pour l’entretien ménager et le nettoyage industriel, d’emballage pour le transport, d’équipements industriels pour buanderie ou pour l’entretien ménager, de système de contrôle contre les déversements ainsi que tout ce que vous avez de besoin dans le monde de la restauration et de l’hôtellerie en passant par la simple coutellerie jusqu’au four spécialisé. Le tout accompagné par un service technique qui fait l’installation, l’entretien et la réparation de votre équipement commercial ou industriel. Également nous offrons un service complet d’entretien ménager et de travaux spécialisés de nettoyage au niveau commercial, industriel et institutionnel. En passant par l’entretien de vos espaces de travail jusqu’au nettoyage de votre système de ventilation, tout y est compris. Nous sommes présents en Abitibi-Témiscamingue, dans le Nord-Est ontarien, à la Baie James, au Nunavik et au Nunavut.", "en": "Sogitex employs 250 people across Abitibi-Témiscamingue. Our goal is to support you with a complete service offering. We distribute janitorial and industrial cleaning products, shipping packaging, industrial laundry and cleaning equipment, spill-control systems, and everything you need in the restaurant and hospitality industries, from basic cutlery to specialized ovens. All this is backed by technical service that installs, maintains and repairs your commercial or industrial equipment. We also provide comprehensive janitorial services and specialized cleaning for commercial, industrial and institutional customers. From maintaining your workspaces to cleaning your ventilation systems, we cover it all. We serve Abitibi-Témiscamingue, northeastern Ontario, James Bay, Nunavik and Nunavut."}, "logo": "assets/logos/exposant-15.png", "website": "https://sogitex.com/", "id": "exposant-15"}, {"name": "Drolet équipements", "description": {"fr": "Nous sommes fiers d'être l'entreprise par excellence, reconnue pour son service adapté aux contraintes de ses clients. Pour tout ce qui trait à l'entretien des routes, rampes et accès, sablage, transport en vrac jusqu'à l'épandage d'abat poussière, l'expertise que nous véhiculons est incontestée. Nos méthodes de travail sont élaborées, nos opérateurs portent le souci de la perfection et ils nous mènent à des projets dont le succès est incontestable. Pour vos travaux souterrains ou de surface, Drolet Équipements est prêt à tout pour vous satisfaire.", "en": "We are proud to be a leading company recognized for service tailored to our customers’ constraints. Our expertise in maintaining roads, ramps and access routes, sanding, bulk transportation and dust-suppressant application is undisputed. Our working methods are carefully developed, and our operators strive for perfection, leading us to successful projects. For your underground or surface work, Drolet Équipements is ready to do everything it takes to satisfy you."}, "logo": "assets/logos/exposant-16.png", "website": "https://6043df65e11e4.site123.me/", "id": "exposant-16"}, {"name": "Eaton industries", "description": {"fr": "Manufacturier de produits de distribution électrique et contrôle industriel.", "en": "A manufacturer of electrical distribution and industrial control products."}, "logo": "assets/logos/exposant-17.png", "website": "https://www.eaton.com/us/en-us.html", "id": "exposant-17"}, {"name": "Electraspec inc", "description": {"fr": "Une agence manufacturière bilingue qui se spécialise dans la représentation d'outils électriques spécialisés, d'automatisation, de fils électriques, de câbles et de produits industriels de sécurité. Ils mettent de l’avant durant cette exposition les produits I-Gard, Cattron, et Techflex, 3 lignes qui s’étendent dans l’industrie minière et Forestière. I-Guard à plus de trente-cinq ans d'expérience nationale et internationale avec une gamme complète de résistances de mise à la terre, de systèmes de protection contre les défauts à la terre et de solutions basées sur des résistances de puissance. I-Gard offre une protection électrique de classe mondiale. Cattron révolutionne la façon dont les industries contrôlent et surveillent leurs opérations. Leader mondial des télécommandes radio, des tableaux de commande de moteurs et de générateurs. Ils proposent une gamme diversifiée de produits et de services offrant des avantages inégalés en termes d'efficacité, de productivité et de sécurité. Et finalement Techflex, qui conçoit et fabrique une large gamme de produits de gaines protectrice pour une variété d'industries allant du biomédical et de l'aérospatiale aux solutions de protection de regroupement de fils, de tuyaux et de câbles. Nous sommes aussi les représentants pour plusieurs autres manufacturiers qui pourrait vous interesser et même vous servir dans votre industrie, pour plus d’information visitez notre site web : electraspec.ca", "en": "A bilingual manufacturers’ representative specializing in electrical tools, automation, electrical wires, cables and industrial safety products. At this exhibition, the agency is showcasing I-Gard, Cattron and Techflex, three product lines serving the mining and forestry industries. I-Gard has more than 35 years of national and international experience and offers a complete range of grounding resistors, ground-fault protection systems and power-resistor-based solutions. I-Gard provides world-class electrical protection. Cattron is transforming how industries control and monitor their operations. A global leader in radio remote controls and engine and generator control panels, it offers a diverse range of products and services with outstanding efficiency, productivity and safety benefits. Techflex designs and manufactures a broad range of protective sleeving products for industries ranging from biomedical and aerospace to solutions that protect bundled wires, hoses and cables. We also represent many other manufacturers that may interest you and serve your industry. For more information, visit electraspec.ca"}, "logo": "assets/logos/exposant-18.png", "website": "http://www.electraspec.ca/", "id": "exposant-18"}, {"name": "Entreprise MB 2014", "description": {"fr": "Entreprise MB se spécialise dans la vente de têtes d’abattage de qualité supérieure. De marque finlandaise TAPIO, dont la réputation n’est plus à faire et pour laquelle nous avons l’exclusivité au Québec, nos bûcheuses vous font gagner temps et argent en forêt. Sur votre tracteur, votre chargeuse, votre pelle, votre excavatrice. Peu importe : elles sont accessibles, légères et peuvent assurément abattre vos gros travaux.", "en": "Entreprise MB specializes in selling high-quality harvesting heads. Our harvesters, from the renowned Finnish brand TAPIO for which we have exclusive distribution rights in Québec, save you time and money in the forest. On your tractor, loader, shovel or excavator—whatever the machine—they are accessible, lightweight and ready to tackle your biggest jobs."}, "logo": "assets/logos/exposant-19.png", "website": "https://entreprisemb2014.com/", "id": "exposant-19"}, {"name": "Epiroc", "description": {"fr": "Epiroc est une partie essentielle d’une société durable et un partenaire mondial de productivité pour ses clients de l’exploitation minière et de l’infrastructure. Grâce à sa technologie révolutionnaire, Epiroc développe et fournit des engins de forage, des équipements et des outils d’excavation du roc et de construction innovants et sécuritaires pour les applications à ciel ouvert et souterraines. L’entreprise offre également des services d’entretien de classe mondiale et un service après-vente de haut niveau, de même que des solutions destinées à l’automatisation, la numérisation et l’électrification. Epiroc, entreprise basée à Stockholm, en Suède, a généré en 2020 un chiffre d’affaires de 36 milliards de couronnes suédoises et est guidée par 14 000 employés passionnés qui soutiennent et collaborent avec des clients dans près de 150 pays. Pour en savoir plus, veuillez visiter le site Web www.epirocgroup.com.", "en": "Epiroc is an essential part of a sustainable society and a global productivity partner for customers in mining and infrastructure. Through its groundbreaking technology, Epiroc develops and supplies innovative, safe drilling rigs, rock-excavation and construction equipment and tools for surface and underground applications. The company also provides world-class maintenance, high-level aftermarket support and solutions for automation, digitalization and electrification. Based in Stockholm, Sweden, Epiroc generated revenue of SEK 36 billion in 2020 and is driven by 14,000 passionate employees who support and collaborate with customers in nearly 150 countries. For more information, visit www.epirocgroup.com."}, "logo": "assets/logos/exposant-20.png", "website": "https://www.epiroc.com/fr-ca", "id": "exposant-20"}, {"name": "Epsilon", "description": {"fr": "offre des services d’ingénierie et de soutien technique spécialisés. Notre équipe étant composée uniquement d’experts en équipements de levage, nous proposons des solutions, novatrices, sécuritaires et fiables qui répondent à vos besoins tout en respectant les plus récentes normes en vigueur. Les concepteurs et ingénieurs d’Epsilon ont supporté plusieurs clients lors de différents mandats d’ingénierie et de services techniques tels que : la conception d’équipements sur mesure, l’augmentation de capacité d’équipements existants, la réfection mécanique et/ou électrique de pont roulant et autres équipements de levage, l’analyse et l’étude d’options, le développement de nouvelles technologies, la mise en service et le démarrage d’équipements, l’installation (licence d’entrepreneur RBQ no. 8324-1109)", "en": "Epsilon offers specialized engineering and technical support services. Our team consists exclusively of lifting-equipment experts, allowing us to provide innovative, safe and reliable solutions that meet your needs while complying with the latest applicable standards. Epsilon’s designers and engineers have supported many customers on engineering and technical service assignments, including custom equipment design, increasing the capacity of existing equipment, mechanical and/or electrical refurbishment of overhead cranes and other lifting equipment, option analysis and evaluation, development of new technologies, commissioning and equipment start-up, and installation (RBQ contractor licence no. 8324-1109)."}, "logo": "assets/logos/exposant-21.png", "website": "https://www.groupeld.com/fr/epsilon", "id": "exposant-21"}, {"name": "Équipements TNO", "description": {"fr": "Il y a près de 50 ans qu’Équipements TNO existe et l’objectif est toujours le même : être au service des entreprises d’ici et du nord de l’Ontario dans l’équipement industriel de tout genre. Il y a déjà 15 ans que le premier tracteur John Deere adapté au milieu minier a été construit dans nos modestes installations. Notre 3e génération de tracteurs miniers est pour nous une grande source de fierté et de motivation. La demande pour ce type de machinerie est sans cesse grandissante, c’est pourquoi désormais cette division opère sous le nom de MINEBUCK et possède ses propres locaux. Outre la fabrication de tracteurs miniers, le service de diagnostique, d’entretien et de réparation de machinerie lourde y est offert. Minebuck, solidement fiable!", "en": "Équipements TNO has been in business for nearly 50 years, with the same goal throughout: serving local businesses and those in northern Ontario with industrial equipment of all kinds. Fifteen years ago, the first John Deere tractor adapted for mining was built in our modest facilities. Our third generation of mining tractors is a major source of pride and motivation. Demand for this type of machinery continues to grow, so this division now operates under the MINEBUCK name and has its own premises. In addition to manufacturing mining tractors, it offers heavy-equipment diagnostics, maintenance and repairs. Minebuck: ruggedly reliable!"}, "logo": "assets/logos/exposant-22.png", "website": "https://equipementstno.com/", "id": "exposant-22"}, {"name": "Everguard incendie et sécurité", "description": {"fr": "Everguard Incendie et Sécurité est une entreprise de vente et de services complets en matière d’incendie et de sécurité qui fournit aux entreprises des produits d’incendie et de sécurité ainsi que les services nécessaires pour protéger leurs investissements, leurs employés, leurs locataires et leurs biens. Notre intégrité, notre honnêteté et notre passion vous permettront de nous faire confiance et assurent une réputation sur laquelle vous pouvez compter. Nos techniciens professionnels sont parmi les plus qualifiés sur le marché et sont formés et certifiés par les fabricants que nous représentons. Pour en savoir plus, visitez notre site web everguardincendiesecurite.com", "en": "Everguard Incendie et Sécurité is a full-service fire and safety sales and service company. It supplies businesses with fire and safety products and the services they need to protect their investments, employees, tenants and property. Our integrity, honesty and passion earn your trust and support a reputation you can rely on. Our professional technicians are among the most qualified in the market and are trained and certified by the manufacturers we represent. For more information, visit everguardincendiesecurite.com"}, "logo": "assets/logos/exposant-23.png", "website": "https://everguardincendiesecurite.com/", "id": "exposant-23"}, {"name": "Fabrication FLM", "description": {"fr": "Fabrication FLM, anciennement connu sous le nom de Ferblanterie Lionel Bertrand, a été établie en 1993. Aujourd’hui, la relève est assurée par les frères Myckel et Maxime Bertrand, qui ont entrepris de faire évoluer l'entreprise en ce modernisant avec l'intégration de machineries à la fine pointe de la technologie. Telle une table laser 6Kw et une table de découpe jet d'eau à 55 000Psi. Ce qui était autrefois une modeste ferblanterie est devenue une entreprise polyvalente spécialisée dans la fabrication métallique industriel léger. Avec plus de 30 ans d'expérience dans le domaine, Myckel et Maxime ont concrétisé une multitude de projets novateurs depuis leur vaste atelier de plus de 10 000 pi² à Amos. Avec un inventaire de plus de 300 000$ de métaux d'acier, d'aluminium et de stainless, ils sont en mesure de réaliser vos projets dans les délais les plus rapides.", "en": "Fabrication FLM, formerly known as Ferblanterie Lionel Bertrand, was established in 1993. Today, brothers Myckel and Maxime Bertrand are leading the next generation, modernizing the business by introducing state-of-the-art machinery such as a 6 kW laser cutting table and a 55,000 psi waterjet cutting table. What was once a modest sheet-metal shop has become a versatile company specializing in light industrial metal fabrication. With more than 30 years of experience, Myckel and Maxime have completed numerous innovative projects from their workshop of more than 10,000 square feet in Amos. With over $300,000 in steel, aluminum and stainless-steel inventory, they can complete your projects with the shortest possible turnaround times."}, "logo": "assets/logos/exposant-24.png", "website": "https://www.flm.ca/", "id": "exposant-24"}, {"name": "Fastenal", "description": {"fr": "Fastenal est une entreprise dédiée à fournir des solutions sur mesure pour les entreprises de divers secteurs. Leur mission est résumée dans la phrase \"le bon produit, au bon endroit, au bon moment.\" Cela reflète leur engagement à aligner leurs services avec les besoins et objectifs uniques de leurs clients. Fastenal y parvient grâce à une combinaison de stocks locaux, de planification proactive et de technologies d'approvisionnement innovantes. En tant que fournisseur unique, Fastenal propose une vaste gamme de produits provenant de plus de 7 300 fournisseurs certifiés. Leurs offres couvrent des catégories telles que les abrasifs, les outils, les équipements de sécurité, et bien plus encore, permettant aux entreprises de consolider leurs fournisseurs et d'optimiser leurs dépenses. De plus, Fastenal propose des solutions avancées comme des distributeurs automatiques, des casiers accessibles 24/7 et des services sur site pour rationaliser les opérations de la chaîne d'approvisionnement et améliorer la productivité. Avec une forte présence locale et une empreinte mondiale, Fastenal assure un soutien fiable et des temps de réponse rapides pour ses clients.", "en": "Fastenal is dedicated to providing tailored solutions for businesses in a variety of sectors. Its mission is expressed in the phrase ‘the right product, in the right place, at the right time.’ This reflects its commitment to aligning its services with each customer’s unique needs and objectives. Fastenal achieves this through a combination of local inventory, proactive planning and innovative supply technologies. As a single-source supplier, Fastenal offers a broad range of products from more than 7,300 certified suppliers. Its offering includes abrasives, tools, safety equipment and much more, allowing businesses to consolidate suppliers and optimize spending. Fastenal also provides advanced solutions such as vending machines, lockers accessible 24/7 and on-site services to streamline supply-chain operations and improve productivity. With a strong local presence and a global footprint, Fastenal delivers reliable support and fast response times for its customers."}, "logo": "assets/logos/exposant-25.jpg", "website": "https://www.fastenal.ca/", "id": "exposant-25"}, {"name": "Filtrartech", "description": {"fr": "Véritable leader en gestion de la poussière, Filtrartech est le seul fournisseur à fabriquer à la fois des vacuums et des dépoussiéreurs industriels, et ce via sa gamme de produits standards ou ses projets développés sur-mesure pour les besoins de ses clients. En plus de fabriquer et vendre ses produits, Filtrartech offre des services d’entretien, d’ingénierie, de location et de distribution de pièces. Innovante, l’entreprise a récemment conçu un produit breveté visant le nettoyage de courroie.Forte de son expertise et sa capacité de production, Filtrartech propose également un service de fabrication de pièces métalliques mécano-soudées.", "en": "A leader in dust management, Filtrartech is the only supplier to manufacture both industrial vacuum systems and dust collectors, through its standard product range and projects custom-developed for customers’ needs. In addition to manufacturing and selling its products, Filtrartech provides maintenance, engineering, rental and parts distribution services. This innovative company recently designed a patented belt-cleaning product. Drawing on its expertise and production capacity, Filtrartech also offers welded metal component fabrication services."}, "logo": "assets/logos/exposant-26.png", "website": "https://filtrartech.com/fr/", "id": "exposant-26"}, {"name": "Fournier & Fils", "description": {"fr": "En affaire depuis plus de 85 ans, L. Fournier & Fils, c’est avant tout une équipe passionnée, reconnue pour sa capacité à planifier, entreprendre et gérer des travaux simples ou complexes et ce, dans n’importe quelles conditions. L. Fournier & Fils se positionne comme l’entrepreneur de choix pour les projets miniers de l’est du Canada. S’appuyant sur une équipe de plus de 1200 employés, avec une flotte de plus de 850 équipements, la capacité de Fournier permet de répondre à tous les besoins de l’industrie minière. Avec son offre de service allant de la construction jusqu’à la fermeture de mines, en passant par son exploitation, Fournier offre des solutions clé en main à ses clients afin de prendre en charge les défis et les risques associés aux projets.", "en": "In business for more than 85 years, L. Fournier & Fils is above all a passionate team, recognized for its ability to plan, undertake and manage simple or complex work under any conditions. L. Fournier & Fils positions itself as the contractor of choice for mining projects in eastern Canada. With more than 1,200 employees and a fleet of over 850 pieces of equipment, Fournier has the capacity to meet all the mining industry’s needs. Its services extend from construction through mine operation and closure, offering turnkey solutions that take on the challenges and risks associated with customers’ projects."}, "logo": "assets/logos/exposant-27.png", "website": "https://www.fournier-fils.com/fr/", "id": "exposant-27"}, {"name": "Franklin Empire", "description": {"fr": "Que ce soit pour le domaine industriel, minier, commercial ou résidentiel, nous sommes les spécialistes dans l'industrie de produits électriques depuis plus de 80 ans. Nous vous offrons : vente et réparations de motorisation & engrenages, automatisation & contrôle, chauffage industriel, distribution électrique et tellement plus encore. Étant le plus important distributeur de produits électrique indépendant au Canada, nous offrons également une équipe d’experts en plusieurs domaines. Avec nos 24 succursales et un accès à plus de 500 fabricants, nous sommes en mesure de vous offrir un approvisionnement partout au Québec, en Ontario ou pour tout site minier au Canada. La plus grande force d’un distributeur indépendant est certainement notre flexibilité et nos possibilités pour accompagner chaque client différemment !", "en": "For more than 80 years, we have been specialists in electrical products for the industrial, mining, commercial and residential sectors. We offer sales and repairs of motors and gearing, automation and control, industrial heating, electrical distribution and much more. As Canada’s largest independent electrical products distributor, we also provide a team of experts in many fields. With 24 branches and access to more than 500 manufacturers, we can supply customers throughout Québec and Ontario and at any mining site in Canada. An independent distributor’s greatest strength is undoubtedly its flexibility and ability to support each customer differently!"}, "logo": "assets/logos/exposant-28.png", "website": "https://franklinempire.com/", "id": "exposant-28"}, {"name": "G4 Drilling", "description": {"fr": "G4, une entreprise fièrement abitibienne ! Notre mission est de fournir des services de forage de qualité et sur mesure pour les industries de l’exploration et de l’exploitation minière grâce à une main-d’œuvre engagée, et ce, de nos employés de terrain jusqu’à la haute direction, tout en s’assurant de maintenir un environnement de travail gratifiant et sécuritaire pour nos équipes. Nous croisons l’expertise de nos différentes entreprises spécialisées dans le domaine du forage pour offrir des services sur mesure : Forage G4, G4 R&D et CCL Forage&Dynamitage. En tant que groupe uni, nos diverses divisions répondent à tous vos besoins en forage souterrain. Avec plus de 25 ans d'expérience, nos divisions spécialisées en forage et dynamitage, ainsi qu'en forage au diamant, sont reconnues dans l'exploitation minière à ciel ouvert. Nous gérons l'ensemble des opérations de forage, dynamitage et ingénierie, selon vos exigences. Que ce soit pour du forage au diamant ou pour du forage long trou, vous pouvez compter sur l’expertise de nos équipes et sur la fiabilité de nos équipements. Faites confiance à la solide expertise de nos équipes !", "en": "G4 is a company proudly rooted in Abitibi! Our mission is to provide quality, customized drilling services for the mineral exploration and mining industries through a committed workforce, from field employees to senior management, while maintaining a rewarding, safe work environment for our teams. We combine the expertise of our specialized drilling companies—Forage G4, G4 R&D and CCL Forage & Dynamitage—to deliver tailored services. As a united group, our divisions meet all your underground drilling needs. With more than 25 years of experience, our divisions specializing in drilling and blasting, as well as diamond drilling, are recognized in surface mining. We manage all drilling, blasting and engineering operations according to your requirements. Whether you need diamond or long-hole drilling, you can count on our teams’ expertise and the reliability of our equipment. Trust the solid expertise of our teams!"}, "logo": "assets/logos/exposant-29.png", "website": "https://g4drilling.com/", "id": "exposant-29"}, {"name": "Georg Fisher - URECON Ltée", "description": {"fr": "Conçoit et fabrique des systèmes de tuyauterie pré isolés au moyen de son procédé d’isolation homogène et sans vide U. I. P.®. pour des applications comme la prévention du gel, l’eau refroidie et l'eau glacée, l’eau chaude et la vapeur utilisées dans les installations municipales, minières, procédés industriels et de chauffage. GF-URECON offre l’assistance lors de la conception, le traçage par Thermocable® et les trousses d’isolation. Les marques Urecon, U.I.P(r), PUR-Split-Tube(r), PEX-Flex(r), Logstor(r) et Cool-Fit-PE-Plus(r) sont toutes des marques de produits frabriquées et distribuées par GeorgFischer-URECON.", "en": "Designs and manufactures pre-insulated piping systems using its uniform, void-free U.I.P.® insulation process for applications such as freeze prevention, chilled and ice water, hot water and steam in municipal and mining facilities, industrial processes and heating systems. GF-URECON provides design assistance, Thermocable® heat tracing and insulation kits. Urecon, U.I.P®, PUR-Split-Tube®, PEX-Flex®, Logstor® and Cool-Fit-PE-Plus® are all product brands manufactured and distributed by GeorgFischer-URECON."}, "logo": "assets/logos/exposant-30.png", "website": "https://www.urecon.com/main/home.html", "id": "exposant-30"}, {"name": "Glass-Shield", "description": {"fr": "Glass-Shield est une entreprise 100 % québécoise spécialisée dans la fabrication et la distribution de peintures industrielles haute performance depuis plus de 50 ans. Nos produits sont conçus pour offrir une résistance exceptionnelle aux impacts, à la corrosion et aux agressions chimiques, assurant la longévité des équipements et infrastructures. Basée à Châteauguay, nous desservons divers secteurs, dont les infrastructures municipales, le ferroviaire, l’hydroélectricité, la pétrochimie ainsi que les industries maritime et minière.. Grâce à notre expertise locale et à un savoir-faire unique, nous développons des solutions adaptées aux conditions environnementales du Québec. Face aux tensions commerciales, nous réaffirmons notre engagement à soutenir l’industrie locale avec des produits fabriqués ici même, respectant les normes environnementales les plus strictes. Choisir Glass-Shield, c’est opter pour l’innovation, la durabilité et la qualité québécoise, tout en contribuant à l’économie locale.", "en": "Glass-Shield is a 100% Québec-based company specializing in the manufacture and distribution of high-performance industrial paints for more than 50 years. Our products are designed to provide exceptional resistance to impacts, corrosion and chemical attack, ensuring long-lasting equipment and infrastructure. Based in Châteauguay, we serve sectors including municipal infrastructure, rail, hydroelectricity, petrochemicals, marine and mining. Through our local expertise and distinctive know-how, we develop solutions adapted to Québec’s environmental conditions. In the face of trade tensions, we reaffirm our commitment to supporting local industry with products made right here that meet the most stringent environmental standards. Choosing Glass-Shield means choosing innovation, durability and Québec quality while contributing to the local economy."}, "logo": "assets/logos/exposant-31.png", "website": "https://www.glass-shield.com/", "id": "exposant-31"}, {"name": "Groupe Altan", "description": {"fr": "Chez Groupe Altan, nous offrons des solutions complètes et adaptées pour vos projets industriels partout au Québec. De la conception à l’installation, notre service clé en main couvre tous les aspects techniques et opérationnels. Notre équipe hautement qualifiée comprend des ingénieurs, chefs de projets, CPI, techniciens, représentants SST, ainsi que des soudeurs, charpentiers, mécaniciens et machinistes expérimentés. Grâce à notre expertise, nous assurons une fabrication industrielle sur mesure, conforme aux normes les plus exigeantes. Nous concevons et certifions des pièces sur mesure avec une précision exceptionnelle pour garantir leur performance optimale. Nos professionnels certifiés CWB réalisent également des soudures sur site afin de simplifier le processus de fabrication. Chaque projet fait l’objet d’une étude de faisabilité rigoureuse, permettant d’évaluer les aspects techniques, financiers et opérationnels afin de minimiser les risques. Nous assurons aussi une gestion complète de projet CAPEX, en prenant en charge toutes les étapes, de la planification à l’exécution, pour garantir efficacité, qualité et respect des délais. Avec Groupe Altan, vous bénéficiez d’un service fiable et personnalisé, conçu pour transformer vos idées en réalisations concrètes et assurer le succès de vos projets industriels.", "en": "At Groupe Altan, we offer comprehensive, tailored solutions for industrial projects throughout Québec. From design to installation, our turnkey service covers every technical and operational aspect. Our highly qualified team includes engineers, project managers, engineering candidates, technicians and occupational health and safety representatives, along with experienced welders, carpenters, mechanics and machinists. Our expertise supports custom industrial fabrication that meets the most demanding standards. We design and certify custom components with exceptional precision to ensure optimal performance. Our CWB-certified professionals also carry out on-site welding to simplify the fabrication process. Every project undergoes a rigorous feasibility study assessing technical, financial and operational factors to minimize risk. We also provide complete CAPEX project management, handling every stage from planning to execution to ensure efficiency, quality and timely delivery. With Groupe Altan, you benefit from reliable, personalized service designed to turn your ideas into practical achievements and make your industrial projects successful."}, "logo": "assets/logos/exposant-32.png", "website": "https://www.groupealtan.com/", "id": "exposant-32"}, {"name": "Groupe CLR Abitibi", "description": {"fr": "Est spécialisé dans la vente, l’installation et l’entretien de réseau de radiocommunication forestier, minier et industriel. Systèmes de radiocommunication par Leaky Feeder, système micro-onde, téléavertisseur, télémétrie. Pour application dans les stations d’épuration et filtration des eaux usées, usines et moulins, ainsi que dans les tunnels et sous terrain.", "en": "Specializes in the sale, installation and maintenance of forestry, mining and industrial radio communications networks. Leaky-feeder radio systems, microwave systems, paging and telemetry, for applications in wastewater treatment and filtration plants, factories and mills, as well as tunnels and underground environments."}, "logo": "assets/logos/exposant-33.png", "website": "http://groupeclr.com/", "id": "exposant-33"}, {"name": "Groupe minier CMAC-Thyssen", "description": {"fr": "Possède l’expertise et les équipements nécessaires pour participer à toutes les étapes de mise en production d’une opération minière. L’entreprise compte à son actif plusieurs réalisations pour des sociétés minières et de construction à travers le monde. CMAC-Thyssen est spécialisé en excavation souterraine de tous genres et pour toutes les applications. Nous fabriquons une gamme d’équipements de forage à l’avant-garde dans l’industrie minière.", "en": "Has the expertise and equipment required to participate in every stage of bringing a mining operation into production. The company has completed numerous projects for mining and construction companies around the world. CMAC-Thyssen specializes in underground excavation of all types and for all applications. We manufacture a range of drilling equipment at the forefront of the mining industry."}, "logo": "assets/logos/exposant-34.png", "website": "https://www.cmac-thyssen.com/", "id": "exposant-34"}, {"name": "HAWE Hydraulik", "description": {"fr": "Le type de valve directionnelle proportionnelle PSL convient aux systèmes de pompage constant et le type PSV aux systèmes de pompe à commande avec régulateur de débit et de pression. Les débits et les pressions peuvent être ajustés individuellement pour chacune des sections. Les valves directionnelles proportionnelles PSL et PSV peuvent être adaptées à différentes tâches: fonctions de sécurité, régularisation de vitesse et limitation des pressions. Toutes les tailles peuvent être combinées les unes avec les autres. En plus Hawe offre une gamme complète de valves cartouche pour les différents type de cavités.Visitez notre site internet pour plus de détails www.hawe.com", "en": "The PSL proportional directional valve is suitable for constant-delivery pump systems, while the PSV type is suitable for variable-displacement pump systems with flow and pressure control. Flow rates and pressures can be adjusted individually for each section. PSL and PSV proportional directional valves can be adapted to different tasks, including safety functions, speed regulation and pressure limitation. All sizes can be combined with one another. HAWE also offers a complete range of cartridge valves for different cavity types. Visit www.hawe.com for more details."}, "logo": "assets/logos/exposant-35.png", "website": "https://www.hydrafab.com/", "id": "exposant-35"}, {"name": "HP Hydraulique", "description": {"fr": "HP Hydraulique est une entreprise qui se spécialise dans la vente et réparation de composantes hydrauliques, pneumatiques, réducteurs planétaires et électromécaniques ainsi que des services en programmation d’hydraulique mobile. En 2015, HP Hydraulique a diversifié ses opérations en créant une division ingénierie, Forcetech Consultants. Forcetech offre des services clé en main en ingénierie mécanique et hydraulique, numérisation 3D et en gestion de projet. Nous sommes distributeurs officiels de la marque renommée de produits Bosch Rexroth, pour le territoire de l’Abitibi-Témiscamingue et Nord du Québec (Ungava). Nous avons obtenu, en 2019, la certification Partenaire d’Excellence Bosch Rexroth pour la distribution dans le domaine de l’hydraulique mobile.", "en": "HP Hydraulique specializes in the sale and repair of hydraulic and pneumatic components, planetary gearboxes and electromechanical components, as well as mobile-hydraulics programming services. In 2015, HP Hydraulique diversified its operations by creating an engineering division, Forcetech Consultants. Forcetech provides turnkey mechanical and hydraulic engineering, 3D scanning and project management services. We are official distributors of the renowned Bosch Rexroth product brand for Abitibi-Témiscamingue and northern Québec (Ungava). In 2019, we obtained Bosch Rexroth’s Certified Excellence Partner certification for distribution in mobile hydraulics."}, "logo": "assets/logos/exposant-36.png", "website": "https://hphydraulique.com/", "id": "exposant-36"}, {"name": "Hydralogie", "description": {"fr": "Fiabilité, productivité, consultation, audits, systèmes hydrauliques, filtration eau, huile, diesel ou tout autre fluide…Hydralogie est une firme spécialisée dans la conception sur mesure de systèmes hydrauliques, de lubrification, de chambres de lubrification, de systèmes de filtration et autres. Nous sommes distributeurs exclusifs de la filtration Pall pour le Québec. Nous nous spécialisons dans l’implantation de programmes de fiabilité, par analyse d’huile, à travers notre division Fluentis. Nous sommes implantés depuis plus de 30 ans, dans toutes les sphères de l’industrie : mines, métaux primaires, pâtes et papier, hydro-électricité, aéronautiques et autres. Nous sommes reconnus grâce à notre expertise, notre savoir-faire et l’efficacité de nos solutions quant au retour sur l’investissement. Nouvelle division HYDRALOGIE DIVISION HYDRAULIQUE : fabrication de cylindres sur mesure.", "en": "Reliability, productivity, consulting, audits, hydraulic systems and filtration of water, oil, diesel or any other fluid… Hydralogie specializes in the custom design of hydraulic systems, lubrication systems and chambers, filtration systems and more. We are the exclusive distributor of Pall filtration products in Québec. Through our Fluentis division, we specialize in implementing reliability programs based on oil analysis. For more than 30 years, we have served all areas of industry, including mining, primary metals, pulp and paper, hydroelectricity, aerospace and others. We are recognized for our expertise, know-how and the effectiveness of our solutions in delivering a return on investment. Our new HYDRALOGIE HYDRAULICS DIVISION manufactures custom cylinders."}, "logo": "assets/logos/exposant-37.png", "website": "http://www.hydralogie.com/", "id": "exposant-37"}, {"name": "Hyperflo", "description": {"fr": "Seul fabriquant québécois de ventilation minière et industrielle. Hyperflo se distingue par son offre de qualité avec les ventilateurs les plus durables sur le marché. Distributeur et fabrication de systèmes de pompage spécialisés en pompes à boue. Relier avec le Groupe VM de Malartic, nous pouvons réparer tous les types de ventilateurs et de pompes. Nous sommes présents pour tout le marcher minier en Abitibi-Témiscamingue, et l’Amérique du Nord.", "en": "Québec’s only manufacturer of mining and industrial ventilation equipment. Hyperflo stands out for its quality offering, with the most durable fans on the market. It also distributes and manufactures pumping systems specializing in slurry pumps. Through our connection with Groupe VM in Malartic, we can repair all types of fans and pumps. We serve the mining market throughout Abitibi-Témiscamingue and North America."}, "logo": "assets/logos/exposant-38.png", "website": "https://www.hyperflo.ca/", "id": "exposant-38"}, {"name": "IBS Tuboquip", "description": {"fr": "IBS, Hardy Filtration, Hipertech Lubrifiant spécialisé, Optibelt, Enerpac, Chesterton, Topring, Luff Industrie", "en": "IBS, Hardy Filtration, Hipertech specialty lubricants, Optibelt, Enerpac, Chesterton, Topring and Luff Industrie."}, "logo": null, "website": "https://ibstuboquip.com/", "id": "exposant-39"}, {"name": "ILEC Industries", "description": {"fr": "DIVISION RADIATEUR JMT : Répare la plupart de tous les radiateurs et refroidisseurs à l’huile sur le marché. Fabrique et conçoit des échangeurs de chaleur sur mesure pour secteur minier et forestier avec procédé éprouvé. Conception en tubes aluminium pour un meilleur refroidissement et nettoyage qui sont monté sur caoutchouc pour contrer les problèmes de vibrations communes de l’industrie. DIVISION LES ATELIERS BORÉAL : Fabrique sur mesure et répare des vérins hydrauliques et pneumatique. Usinage de pièces avec machine conventionnelle ou numérique à partir de plan et de pièces ajustés selon les normes du client.", "en": "RADIATEUR JMT DIVISION: Repairs most radiators and oil coolers available on the market. Designs and manufactures custom heat exchangers for the mining and forestry sectors using a proven process. Aluminum-tube designs improve cooling and cleaning; rubber mounting addresses the vibration problems common in the industry.\n\nLES ATELIERS BORÉAL DIVISION: Custom-manufactures and repairs hydraulic and pneumatic cylinders. Machines parts using conventional or CNC equipment from drawings and components, with adjustments to meet customers’ standards."}, "logo": "assets/logos/exposant-40.png", "website": "https://www.ilecindustries.ca/fr/", "id": "exposant-40"}, {"name": "KAL Tire", "description": {"fr": "KAL Tire est une entreprise familiale canadienne avec des succursales à travers le Canada. Nous avons deux magasins en Abitibi qui ont accès à une vaste gamme de pneus pour soutenir non seulement les mines, mais aussi les gens qui conduisent dans la région.", "en": "KAL Tire is a Canadian family-owned company with branches across Canada. We have two stores in Abitibi with access to a broad selection of tires to support both mines and people driving in the region."}, "logo": "assets/logos/exposant-41.png", "website": "https://www.kaltire.com/", "id": "exposant-41"}, {"name": "Levert Group", "description": {"fr": "Description à venir sous peu", "en": "Description coming soon."}, "logo": "assets/logos/exposant-42.png", "website": "https://levert.ca/", "id": "exposant-42"}, {"name": "Location MSN", "description": {"fr": "Implantée depuis 20 ans dans sa communauté, Location MSN se spécialise dans la location, la vente et la réparation d’outils et d’équipements. Ils représentent plusieurs marques telles que Manitou, Red Lift et Dynablast. L’agrandissement récent de leur bâtisse leur a permis d’être la référence dans la réparation des équipements de levage. Ainsi, ils peuvent également aller de l’avant dans la recherche et l'innovation, comme en témoigne la vente du premier chariot télescopique à commande indépendante au panier. Une première mondiale réalisée dernièrement. Avec Location MSN « La réussite commence par le service ! ».", "en": "Established in its community for 20 years, Location MSN specializes in renting, selling and repairing tools and equipment. It represents brands such as Manitou, Red Lift and Dynablast. A recent building expansion has made it a leading provider of lifting-equipment repairs. It is also advancing research and innovation, as shown by the recent sale of the first telehandler with independent controls in the platform—a world first. With Location MSN, ‘success begins with service!’"}, "logo": "assets/logos/exposant-43.jpg", "website": "https://locationmsn.ca/", "id": "exposant-43"}, {"name": "M & M Nord Ouest", "description": {"fr": "Fondée en 1937, c’est une entreprise de distribution pour l’industrie minière et forestière, en pièces automobiles, produits de carrosseries, outillages et équipements industriels, produits de soudure, produits sanitaires, vêtements de travail, équipements de sécurité et de boulonneries. Nous sommes distributeur EXCLUSIF des systèmes de rangement : ROUSSEAU MÉTAL pour l’Abitibi-Témiscamingue et Nord-du-Québec. Entreprise du GROUPE BOISSONNEAULT.", "en": "Founded in 1937, the company distributes products for the mining and forestry industries, including automotive parts, bodywork products, industrial tools and equipment, welding products, sanitation products, workwear, safety equipment and fasteners. We are the EXCLUSIVE distributor of ROUSSEAU MÉTAL storage systems for Abitibi-Témiscamingue and northern Québec. A GROUPE BOISSONNEAULT company."}, "logo": "assets/logos/exposant-44.png", "website": "https://mmnordouest.com/", "id": "exposant-44"}, {"name": "Machinerie Avantis – J. René Lafonds", "description": {"fr": "Description à venir.", "en": "Description coming soon."}, "logo": "assets/logos/exposant-45.png", "website": "https://machinerieavantis.ca/succursales/j-rene-lafond-inc/", "id": "exposant-45"}, {"name": "Machinerie St-Pierre", "description": {"fr": "En affaire depuis plus de 35 ans. Nous faisons la vente, la location et l’achat d’équipement. Nous sommes distributeur Prinoth, Muddox, Sherp, Starke lift. Si vous cherchez un équipement spécifique nous faisons les recherches, l’importation et aussi la location de celui-ci lorsque désiré. Nous avons aussi des mécaniciens et des camions de service pour vous offrir ce service autant en atelier que sur la route. Nous offrons aussi le transport et la récupération de matériel en milieu hostile. Venez nous voir au 3392 chemin Sullivan. Nous somme votre partenaire pour vos travaux hors route et le service est pour nous une valeur!", "en": "In business for more than 35 years, we sell, rent and purchase equipment. We distribute Prinoth, Muddox, Sherp and Starke Lift products. If you need a specific piece of equipment, we handle the search, importation and rental when requested. Our mechanics and service trucks provide support both in the shop and on the road. We also offer transportation and equipment recovery in challenging environments. Visit us at 3392 chemin Sullivan. We are your partner for off-road work, and service is one of our core values!"}, "logo": "assets/logos/exposant-46.png", "website": "https://www.machineriestpierre.com/", "id": "exposant-46"}, {"name": "Machines Roger International", "description": {"fr": "Compagnie manufacturière, œuvrant dans la fabrication d’outils de forage spécialisés. La compagnie est aussi un important entrepreneur, offrant des services de forage à l’industrie minière. Avec un parc d’équipement comportant plus de soixante foreuses, Machines Roger International est en mesure de rencontrer tous les besoins en forage d’exploration souterrain, forage de production et forage de trou de service pour ses nombreux clients. Machines Roger International – au service de l’industrie minière depuis plus de 35 ans.", "en": "A manufacturing company producing specialized drilling tools. The company is also a major contractor providing drilling services to the mining industry. With a fleet of more than 60 drills, Machines Roger International can meet its many customers’ needs for underground exploration drilling, production drilling and service-hole drilling. Machines Roger International has served the mining industry for more than 35 years."}, "logo": "assets/logos/exposant-47.png", "website": "https://www.machines-roger.ca/", "id": "exposant-47"}, {"name": "MacLean Engineering", "description": {"fr": "La compagnie MacLean Engineering se spécialise dans la conception, la fabrication, et la mise en marché d’équipement mobile dans le secteur minier. La compagnie, qui souligne 50 ans d’activités commerciales en 2023, dispose désormais d'une plateforme de fabrication sur tout le continent nord-américain, des succursales de service et d'assistance à travers le Canada de même qu’aux États-Unis, au Mexique, au Pérou, en Afrique du Sud et en Australie.", "en": "MacLean Engineering specializes in designing, manufacturing and marketing mobile equipment for the mining sector. The company, which celebrated 50 years in business in 2023, now has a manufacturing platform across North America and service and support branches throughout Canada, as well as in the United States, Mexico, Peru, South Africa and Australia."}, "logo": "assets/logos/exposant-48.png", "website": "https://macleanengineering.com/", "id": "exposant-48"}, {"name": "Maison Nordique", "description": {"fr": "Description à venir.", "en": "Description coming soon."}, "logo": "assets/logos/exposant-49.png", "website": "https://maisonnordique.com/", "id": "exposant-49"}, {"name": "Manufacture Sling Choker Ltée", "description": {"fr": "Bien plus que vous pensez! Fabrication, inspection, réparation et certification de tous types d’équipements de levage incluant : palans à chaîne manuels et électriques, élingues, potences, pont-roulants, treuils, etc. Distributeur d’une large gamme de produits industriels pour les secteurs miniers et forestiers. Distributeur d’équipements de protection et sécurité et d’équipements anti-chutes.Vaste gamme de pompes industrielles submersibles et stationnaires ainsi qu’un atelier de réparation de pompes à la fine pointe. Succursale Val-d'Or : 1400, rue Fournier, Val-d'Or (Québec) J9P 6X8 / T : 819 825-4747 ventevaldor@slingchoker.com // Succursale Rouyn-Noranda : 1050, rue Saguenay, Rouyn-Noranda (Québec) J9X 7B6 / T : 819 797-3384 ventenoranda@slingchoker.com", "en": "Much more than you might think! Manufacturing, inspection, repair and certification of all types of lifting equipment, including manual and electric chain hoists, slings, jib cranes, overhead cranes, winches and more. Distributor of a broad range of industrial products for the mining and forestry sectors, protective and safety equipment, and fall-protection equipment. A wide range of submersible and stationary industrial pumps, supported by a state-of-the-art pump repair shop.\n\nVal-d’Or branch: 1400, rue Fournier, Val-d’Or (Québec) J9P 6X8. Tel.: 819 825-4747. ventevaldor@slingchoker.com\n\nRouyn-Noranda branch: 1050, rue Saguenay, Rouyn-Noranda (Québec) J9X 7B6. Tel.: 819 797-3384. ventenoranda@slingchoker.com"}, "logo": "assets/logos/exposant-50.png", "website": "https://www.slingchoker.com/", "id": "exposant-50"}, {"name": "Marcotte Inc.", "description": {"fr": "Marcotte Inc. est une entreprise manufacturière spécialisée dans l’équipement de forage au diamant et la fabrication de structures d’acier pour le secteur minier. Elle agit également comme distributeur de produits variés, incluant des huiles bios et des composites.", "en": "Marcotte Inc. is a manufacturing company specializing in diamond-drilling equipment and steel structures for the mining sector. It also distributes a variety of products, including bio-based oils and composites."}, "logo": "assets/logos/exposant-51.png", "website": "https://um-vd.com/", "id": "exposant-51"}, {"name": "Mascoutech", "description": {"fr": "Mascoutech a débuté ses activités en 1979 en se spécialisant dans les fournitures et l'outillage industriels. Au fil des années, nous avons développé nos produits en matière de découpe, de perçage et de carottage pour l'industrie métallurgique, notamment le secteur de l'acier. Aujourd'hui, nous pouvons percer presque tous les alliages existants ! Nous fournissons aussi des produits pour la maintenance, la construction, l'usinage, etc. Les clients sont assurés d'obtenir ce dont ils ont besoin pour l'exécution de leurs opérations. Nous considérons que la qualité des produits n'est pas négociable, c'est pourquoi la plupart des produits sont européens. Notre service comprend des visites d'atelier, des démonstrations et des formations sur nos produits pour des performances optimales, un support technique pour aider les clients à faire le bon choix et la mise en place de séminaires pour la force de vente de nos distributeurs. Tout cela nous distingue de la concurrence!", "en": "Mascoutech began operating in 1979, specializing in industrial supplies and tools. Over the years, we have developed our cutting, drilling and core-drilling products for the metals industry, particularly the steel sector. Today, we can drill through almost every existing alloy! We also supply products for maintenance, construction, machining and more, ensuring customers have what they need to carry out their operations. We consider product quality non-negotiable, which is why most of our products are European. Our service includes workshop visits, product demonstrations and training for optimal performance, technical support to help customers make the right choice, and seminars for our distributors’ sales teams. All of this sets us apart from the competition!"}, "logo": "assets/logos/exposant-52.png", "website": "https://www.mascoutech.com/", "id": "exposant-52"}, {"name": "McDowell", "description": {"fr": "McDowell B. Equipment Ltd. fournit des équipements de construction neufs et récents en location ou en vente. Le parc de véhicules de location de la société comprend des chargeuses souterraines de 1/2 à 10 m, des camions de transport souterrain de 7 à 40 tonnes, des niveleuses compactes, des foreuses à une, deux ou trois rampes, des camions malaxeurs souterrain, des locomotives et des wagons. McDowell fabrique des machines à Shotecrete, des nacelles à ciseaux, des chargeuses Anfo et du personnel transporteur. La société peut également proposer des équipements entièrement reconstruits ou remis à neuf avec des économies substantielles et des délais de livraison rapides. Un nouveau programme d'échange de pièces offre aux clients la possibilité d'échanger immédiatement des pièces contre des pièces reconstruites, ce qui leur permet d'économiser un temps précieux ou des coûts d'inventaire.", "en": "McDowell B. Equipment Ltd. offers new and late-model construction equipment for rental or sale. Its rental fleet includes underground loaders from 1/2 to 10 m, underground haul trucks from 7 to 40 tonnes, compact graders, one-, two- and three-boom drills, underground concrete mixer trucks, locomotives and railcars. McDowell manufactures shotcrete machines, scissor lifts, ANFO loaders and personnel carriers. The company also offers fully rebuilt or refurbished equipment with substantial savings and quick delivery times. A new parts-exchange program allows customers to immediately exchange parts for rebuilt units, saving valuable time and inventory costs."}, "logo": "assets/logos/exposant-53.png", "website": "https://www.bmcdowell.com/", "id": "exposant-53"}, {"name": "MineOps", "description": {"fr": "MineOps se démarque au sein de l’industrie minière en offrant des services d’exception, capables de répondre aux exigences les plus élevées, grâce à une approche proactive, une ingéniosité constante et un professionnalisme sans compromis. MineOps est un partenaire de confiance, offrant des solutions efficaces dans la mise à disposition de travailleurs qualifiés, ainsi que des services miniers de surface, souterrains et de location d’équipements. L’entreprise offre son expertise à travers trois axes de spécialisation : l’approvisionnement en main-d’œuvre compétente et adaptée aux besoins spécifiques de ses clients, le développement d’infrastructures minières, incluant le forage, le dynamitage et les travaux de développement, ainsi que la maintenance industrielle, notamment en mécanique, soudage et tuyauterie, pour les usines de traitement et les sites miniers. Grâce à son solide réseau et son expertise terrain, MineOps aide ses clients à relever leurs défis en matière de construction, de maintenance et d’exploitation minière.", "en": "MineOps stands out in the mining industry by delivering exceptional services that meet the highest requirements through a proactive approach, constant ingenuity and uncompromising professionalism. MineOps is a trusted partner, providing effective solutions for skilled workforce placement, surface and underground mining services, and equipment rentals. The company offers expertise in three specialized areas: supplying competent workers suited to customers’ specific needs; developing mining infrastructure, including drilling, blasting and development work; and providing industrial maintenance, particularly mechanical work, welding and piping for processing plants and mining sites. Through its strong network and field expertise, MineOps helps customers meet their construction, maintenance and mining-operation challenges."}, "logo": "assets/logos/exposant-54.png", "website": "https://www.mineops.com/", "id": "exposant-54"}, {"name": "Moteur du Cuivre / Zuritt", "description": {"fr": "Moteur du Cuivre inc. est une compagnie de distribution de produits électriques industrielles établies depuis plus de 30 ans œuvrant en Abitibi Témiscamingue, Nord Ontario, Nord-du-Québec et dans quelques pays à l’extérieur du Canada. En plus d’offrir des produits hauts de gamme dans le contrôle de la motorisation, nous avons une très grande expertise concernant les variateurs de vitesse ( dimensionnement, questions technique, formation, démarrage) . Nos principaux clients sont l’industrie Minière et l’industrie Forestière.", "en": "Moteur du Cuivre inc. is an industrial electrical products distributor established more than 30 years ago, serving Abitibi-Témiscamingue, northern Ontario, northern Québec and several countries outside Canada. In addition to high-end motor-control products, we offer extensive expertise in variable-speed drives, including sizing, technical questions, training and start-up. Our main customers are in the mining and forestry industries."}, "logo": "assets/logos/exposant-55.png", "website": "https://www.facebook.com/p/ZurittMoteur-du-cuivre-61559156759959/?locale=fr_CA", "id": "exposant-55"}, {"name": "Nano Revêtement Thermique Inc", "description": {"fr": "Nano Revêtement Thermique – L’Excellence en Revêtements Spécialisés pour les Secteurs Minier, Ferroviaire et Maritime Innovation, performance et durabilité. Voilà ce qui définit Nano Revêtement Thermique, un acteur incontournable dans l’industrie des revêtements spécialisés. Grâce à des partenariats stratégiques avec des manufacturiers de premier plan, nous développons des méthodes d’application novatrices et exploitons des équipements à la fine pointe de la technologie pour répondre aux exigences rigoureuses des secteurs minier, ferroviaire et maritime. Une expertise adaptée aux environnements extrêmes Dans le secteur minier, où les équipements et infrastructures sont soumis à des conditions extrêmes – abrasion, corrosion, températures élevées – nos revêtements spécialisés offrent une protection optimale pour prolonger la durée de vie des installations et améliorer leur efficacité opérationnelle. Pour l’industrie ferroviaire, nous proposons des solutions de revêtement qui renforcent la résistance des structures métalliques, réduisent l’usure des composants et améliorent la performance énergétique des équipements roulants. Nos technologies permettent également d’optimiser la protection contre les intempéries et les contaminants. Quant au secteur maritime, où la corrosion due à l’eau salée et les conditions climatiques sévères sont des défis constants, nous développons des revêtements avancés assurant une résistance supérieure, réduisant les coûts de maintenance et prolongeant la durée de vie des navires, plateformes et infrastructures portuaires. Un engagement envers l’innovation et la performance Chez Nano Revêtement Thermiques, nous ne cessons d’innover pour offrir des solutions de revêtement thermiques, anticorrosion et protectrices adaptées aux environnements les plus exigeants. Notre engagement envers la qualité, la durabilité et l’efficacité fait de nous un partenaire de confiance pour les entreprises qui recherchent des performances accrues et une réduction des coûts d’entretien. Avec une expertise éprouvée, des technologies de pointe et une approche sur mesure, nous repoussons les limites des revêtements industriels pour assurer la protection et l’optimisation des infrastructures essentielles aux secteurs minier, ferroviaire et maritime.", "en": "Nano Revêtement Thermique — Excellence in Specialized Coatings for the Mining, Rail and Marine Sectors.\n\nInnovation, performance and durability define Nano Revêtement Thermique, a key player in specialized coatings. Through strategic partnerships with leading manufacturers, we develop innovative application methods and use state-of-the-art equipment to meet the demanding requirements of the mining, rail and marine sectors.\n\nExpertise adapted to extreme environments. In mining, where equipment and infrastructure face extreme abrasion, corrosion and high temperatures, our specialized coatings provide optimal protection, extend installation life and improve operational efficiency. For the rail industry, we offer coatings that strengthen metal structures, reduce component wear and improve the energy performance of rolling stock. Our technologies also optimize protection against weather and contaminants. In the marine sector, where saltwater corrosion and severe weather present constant challenges, we develop advanced coatings that provide superior resistance, reduce maintenance costs and extend the life of ships, platforms and port infrastructure.\n\nA commitment to innovation and performance. At Nano Revêtement Thermique, we continuously innovate to deliver thermal, anti-corrosion and protective coatings suited to the most demanding environments. Our commitment to quality, durability and efficiency makes us a trusted partner for businesses seeking higher performance and lower maintenance costs. With proven expertise, advanced technologies and a tailored approach, we push the boundaries of industrial coatings to protect and optimize essential infrastructure in mining, rail and marine industries."}, "logo": "assets/logos/exposant-56.png", "website": "https://nanothermalcoating.com/", "id": "exposant-56"}, {"name": "Nedco", "description": {"fr": "Nedco est une bannière de Rexel, leader mondial en distribution de produits, de services et de solutions électriques. Nedco est l’un des distributeurs électriques et de communication de données les plus complets au Canada avec 69 succursales à l’échelle du pays. Nedco propose une large gamme de produits de qualité dans les secteurs suivants : éclairage, communication de données, fils et câbles, gestion d’énergie et matériel électrique.", "en": "Nedco is a Rexel banner, part of a global leader in the distribution of electrical products, services and solutions. With 69 branches nationwide, Nedco is one of Canada’s most comprehensive electrical and data communications distributors. Nedco offers a broad range of quality products in lighting, data communications, wire and cable, energy management and electrical supplies."}, "logo": "assets/logos/exposant-57.png", "website": "https://www.nedco.ca/cnd/", "id": "exposant-57"}, {"name": "Nord-Flo / Lubex", "description": {"fr": "Oeuvrant dans le domaine des pompes depuis plus de 31 ans, Nord-Flo est formée d'une équipe grandement qualifiée qui mise sur la qualité irréprochable de son service. Que ce soit au niveau municipal, industriel ou minier, sa grande connaissance des pompes lui permet d’assurer à sa clientèle une expertise hors pair.", "en": "With more than 31 years in the pump industry, Nord-Flo has a highly qualified team committed to impeccable service quality. Whether in municipal, industrial or mining applications, its extensive pump knowledge provides customers with outstanding expertise."}, "logo": "assets/logos/exposant-58.png", "website": "https://www.nord-flo.com/", "id": "exposant-58"}, {"name": "Normet", "description": {"fr": "Normet est une entreprise technologique de premier plan qui offre une amélioration continue des processus de creusement de tunnels et d’exploitation minière souterraine pour accroître la sécurité, la productivité et la rentabilité. Nous travaillons en étroite collaboration avec nos clients et utilisons notre expertise en matière de processus accumulée sur des milliers de projets de tunnels et de mines dans le monde entier pour des actions concrètes et des résultats financiers pour nos clients. Nous avons une vaste offre souterraine, y compris des équipements pour la projection et le transport du béton, le chargement d’explosifs, l'écaillage, le levage, les travaux d’installation et la logistique,des systèmes de de brise-roche et piédestal. Nous fournissons des produits chimiques de construction pour le béton projeté, des adjuvants, des systèmes d’injection pour le contrôle du sol et de l’eau, des systèmes d’étanchéité et des additifs pour la technologie TBM. Nous avons des produits de renforcement de roche innovants et de haute qualité qui réduisent le risque d’accidents dans des conditions rocheuses difficiles. Nos services visent à assurer la sécurité et la productivité de nos clients tout au long du cycle de vie, y compris la fourniture de pièces de rechange la location d’équipement, la remise à neuf et les mises à niveau, les services sur le terrain, la formation et plus encore.", "en": "Normet is a leading technology company that continuously improves tunnelling and underground mining processes to increase safety, productivity and profitability. We work closely with customers and draw on process expertise gained from thousands of tunnelling and mining projects worldwide to deliver practical actions and financial results. Our extensive underground offering includes equipment for concrete spraying and transport, explosives charging, scaling, lifting, installation work and logistics, as well as rock-breaker and pedestal systems. We supply construction chemicals for shotcrete, admixtures, injection systems for ground and water control, waterproofing systems and additives for TBM technology. Our innovative, high-quality rock-reinforcement products reduce accident risks in difficult rock conditions. Our services support customer safety and productivity throughout the equipment life cycle, including spare parts, equipment rental, refurbishment and upgrades, field services, training and more."}, "logo": "assets/logos/exposant-59.png", "website": "http://www.normet.com/", "id": "exposant-59"}, {"name": "OK PNEUS Val-d'Or", "description": {"fr": "OK PNEUS Val-d'Or offre des pneus miniers, camion commercial, forestier, construction et industriel, agricole et véhicule légers. Notre bannière pancanadienne détient un inventaire impressionnant et varié pour répondre aux besoins spécifiques de notre clientèle. Les produits offerts parmi les plus grands fabricants sur le marché, tel que BRIDGESTONE, MICHELIN, BKT, TOYO, CONTIENTAL, TRIANGLE, GOODRIDE etc. Notre service rapide et professionnel comprend des unités mobiles disponibles 7/7 24/24 dispensés par nos camions flèche et camions service directement aux sites miners.OK PNEUS Val d'Or votre partenaire pour que vos opérations roule sur l'or!", "en": "OK PNEUS Val-d’Or offers tires for mining, commercial trucks, forestry, construction, industrial and agricultural equipment, and light vehicles. Our Canada-wide banner maintains an extensive, diverse inventory to meet customers’ specific needs, with products from major manufacturers such as BRIDGESTONE, MICHELIN, BKT, TOYO, CONTINENTAL, TRIANGLE, GOODRIDE and others. Our fast, professional service includes mobile units available 24 hours a day, 7 days a week, with boom trucks and service trucks working directly at mining sites. OK PNEUS Val-d’Or: your partner in keeping operations rolling toward gold!"}, "logo": "assets/logos/exposant-60.png", "website": "https://www.facebook.com/OKPneusValdOrCommercial?locale=fr_CA", "id": "exposant-60"}, {"name": "Petronor", "description": {"fr": "En tant que fournisseur essentiel d’énergie pour les territoires du nord du Québec depuis plus de 20 ans, PétroNor est fier d’être le Distributeur exclusif des lubrifiants Pétro-Canada. Nous livrons avec fierté une large gamme de produits pétroliers tel que diesel, essence et carburants d’aviation en formats emballés et en vrac, par camion, répondant ainsi aux divers besoins de nos clients. Notre équipe dévouée excelle à surmonter les défis logistiques, garantissant que vous recevez les produits dont vous avez besoin, exactement quand et où vous en avez besoin tout en mettant la sécurité au cœur de nos actions.", "en": "An essential energy supplier to northern Québec for more than 20 years, PétroNor is proud to be the exclusive distributor of Petro-Canada lubricants. We deliver a wide range of petroleum products, including diesel, gasoline and aviation fuels, in packaged and bulk formats by truck to meet our customers’ diverse needs. Our dedicated team excels at overcoming logistical challenges, ensuring that you receive the products you need exactly when and where you need them, with safety at the heart of everything we do."}, "logo": "assets/logos/exposant-61.png", "website": "https://petronor.ca/", "id": "exposant-61"}, {"name": "Plastiques industriels G Plus", "description": {"fr": "Plastiques G+ est le partenaire de confiance des professionnels miniers pour la conception et la fabrication de solutions en polymères haute performance. Depuis trois décennies, nous mettons notre savoir-faire unique au service des défis spécifiques de l'industrie minière.Notre équipe multidisciplinaire maîtrise les propriétés uniques des polymères et leur application dans l'environnement exigeant des mines. Cette expertise nous permet de développer des produits innovants, particulièrement dans les domaines critiques de la ventilation minière, les équipements de santé et de sécurité ainsi que les composants résistants à l’abrasion et à la corrosion.Chez Plastiques G+, nous sommes convaincus que l'innovation naît de la collaboration. C'est pourquoi nous travaillons en étroite synergie avec nos clients miniers pour développer les solutions polymères qui façonneront l'avenir de l'industrie minière.", "en": "Plastiques G+ is a trusted partner for mining professionals in the design and manufacture of high-performance polymer solutions. For three decades, we have applied our distinctive expertise to the mining industry’s specific challenges. Our multidisciplinary team understands polymers’ unique properties and their use in demanding mining environments. This expertise allows us to develop innovative products, particularly in critical areas such as mine ventilation, health and safety equipment, and abrasion- and corrosion-resistant components. At Plastiques G+, we believe innovation grows out of collaboration. We therefore work closely with mining customers to develop the polymer solutions that will shape the industry’s future."}, "logo": "assets/logos/exposant-62.png", "website": "https://plastiquesgplus.com/", "id": "exposant-62"}, {"name": "Pneu GBM", "description": {"fr": "PNEUS GBM – UN LEADER DANS LE DOMAINE DU PNEU AU QUÉBEC. Pneus GBM est une entreprise bien établie en Abitibi-Témiscamingue depuis 2004 qui compte 11 succursales et un centre de distribution, s’étendant de Mont-Laurier jusqu’au Nord-du-Québec en passant par l’Abitibi-Témiscamingue. Nous desservons une clientèle diversifiée dans le secteur minier, forestier et industriel.Nous sommes un chef de file dans la vente, l’installation et la réparation de pneus, offrant un service de dépannage 24h/24 – 7 jours/7 aux entreprises. De plus, nos succursales de Ville-Marie et Val-d’Or proposent un service de mécanique automobile. Grâce à plus de 20 ans d’expertise, nous avons su nous démarquer par notre rapidité et notre efficacité sur le terrain. Face à une forte demande régionale, 10 de nos succursales sont spécialisées dans les pneus de machinerie lourde (OTR – Off The Road), essentiels aux entreprises œuvrant sur des chantiers exigeants. UNE EXPERTISE RENFORCÉE GRÂCE À ROBERT BERNARD. En intégrant le réseau Robert Bernard, un acteur majeur dans l’industrie des pneus et de la mécanique au Québec depuis 1950, Pneus GBM bénéficie d’un appui solide et d’un savoir-faire reconnu. Cette expansion nous permet de renforcer notre présence à travers la province, passant de 21 à 31 succursales, et d’unir nos forces pour mieux servir notre clientèle. Robert Bernard est une entreprise familiale, employant désormais 650 experts dans le domaine, et partage les mêmes valeurs que Pneus GBM : engagement, expertise et excellence. Cette alliance stratégique nous permet d’offrir un service encore plus complet et performant à nos partenaires de l’industrie minière et aux entreprises de la région.", "en": "PNEUS GBM — A LEADER IN QUÉBEC’S TIRE INDUSTRY.\n\nEstablished in Abitibi-Témiscamingue since 2004, Pneus GBM has 11 branches and a distribution centre, extending from Mont-Laurier through Abitibi-Témiscamingue to northern Québec. We serve a diverse customer base in mining, forestry and industry. We are a leader in tire sales, installation and repair, offering businesses emergency roadside assistance 24 hours a day, 7 days a week. Our Ville-Marie and Val-d’Or branches also provide automotive mechanical services. With more than 20 years of expertise, we have distinguished ourselves through speed and efficiency in the field. In response to strong regional demand, 10 branches specialize in heavy-equipment tires (OTR — Off The Road), essential for businesses working on demanding sites.\n\nEXPERTISE STRENGTHENED THROUGH ROBERT BERNARD. By joining the Robert Bernard network, a major player in Québec’s tire and mechanical services industry since 1950, Pneus GBM benefits from solid support and recognized expertise. This expansion strengthens our provincial presence, increasing the network from 21 to 31 branches and bringing our strengths together to better serve customers. Robert Bernard is a family-owned business now employing 650 experts and shares Pneus GBM’s values of commitment, expertise and excellence. This strategic alliance enables us to provide even more comprehensive, effective service to our mining partners and regional businesses."}, "logo": "assets/logos/exposant-63.png", "website": "https://pneusgbm.com/succursales/la-sarre/", "id": "exposant-63"}, {"name": "Polyplast", "description": {"fr": "Entreprise manufacturière dans le domaine du moulage de pièces de polyuréthane rigides, semi-rigides et flexibles. Nous travaillons en partenariat avec les entreprises afin de maximiser leur rendement, leur productivité et amoindrir leurs coûts de production et de maintenance.", "en": "A manufacturer specializing in moulding rigid, semi-rigid and flexible polyurethane parts. We work in partnership with businesses to maximize performance and productivity while reducing production and maintenance costs."}, "logo": "assets/logos/exposant-64.jpg", "website": "https://polyplasts.com/", "id": "exposant-64"}, {"name": "Pompaction", "description": {"fr": "Compagnie qui fournit des systèmes de pompage et de bétonnage de qualité supérieure adaptés aux besoins de nos clients. Que ce soit pour la vente, la location ou les réparations, nous offrons un service hors pair afin d’assurer la performance optimale et durable de nos produits.", "en": "A company providing high-quality pumping and concreting systems tailored to customers’ needs. Whether for sales, rentals or repairs, we offer outstanding service to ensure optimal, lasting product performance."}, "logo": "assets/logos/exposant-65.png", "website": "https://www.pompaction.com/", "id": "exposant-65"}, {"name": "Pro Tech Power", "description": {"fr": "Pro-Tech Power Inc. est un Représentant Manufacturier en équipements électriques de puissance, Notre mission est de fournir le plus haut niveau de service à la fois à nos clients et manufacturiers. Nous nous engageons à offrir notre expérience à nos clients, dans la sélection des meilleurs solutions techniques, et dans un respect des budgets. G&W Electric : Un manufacturier d’appareillages électriques avec 120 ans d’histoire. G&W se spécialise dans les équipements de distribution à moyenne tension à isolation solide et au gaz, construit selon les besoins de ses clients, en plus d’offrir de épissures et terminaisons de câbles moyenne et haute tension. Doble / Morgan Schaffer : Est un leader mondialement reconnu pour les équipements d’essais sur les appareillages électriques et ses expert technique dans plusieurs domaines. Avec plus de 100 ans d’histoire et de nombreuse acquisition dans les dernières années dont Morgan Schaffer à Montréal, un laboratoire d’analyse d’huile isolante de réputation mondial dans les gaz dissous. Morgan Schaffer offre aussi une gamme complète de moniteurs de DGA en continu. AltaNova : Dernière acquisition de Doble, offre une gamme d’équipement mesure des décharges partielles et température dans les câbles et appareillages. www.doble.com , www.gwelec.com , www.pro-techpower.com", "en": "Pro-Tech Power Inc. is a manufacturers’ representative for electrical power equipment. Our mission is to provide the highest level of service to both customers and manufacturers. We are committed to using our experience to help customers choose the best technical solutions while respecting their budgets.\n\nG&W Electric: A manufacturer of electrical switchgear with 120 years of history. G&W specializes in solid- and gas-insulated medium-voltage distribution equipment built to customers’ requirements, as well as medium- and high-voltage cable joints and terminations.\n\nDoble / Morgan Schaffer: A globally recognized leader in electrical equipment testing and technical expertise across many fields. Doble has more than 100 years of history and has made numerous acquisitions in recent years, including Morgan Schaffer in Montréal, an insulating-oil analysis laboratory with a worldwide reputation in dissolved-gas analysis. Morgan Schaffer also offers a complete range of continuous DGA monitors.\n\nAltaNova: Doble’s latest acquisition offers equipment for measuring partial discharge and temperature in cables and electrical equipment. www.doble.com, www.gwelec.com, www.pro-techpower.com"}, "logo": "assets/logos/exposant-66.png", "website": "https://www.pro-techpower.com/products-and-locations/quebec/", "id": "exposant-66"}, {"name": "Produits Miniers Wilson", "description": {"fr": "Depuis 40 ans Produits Miniers Wilson distribuent des produits de haut qualite a ses clients au travere du monde. Nos produits : Versa Matic – Pompes a diaphragme, Ictus – Pompes a ciment, PHQ – Foreuse 250 et S36, Bex – Chargeur a Amex, Ingersoll Rand – Treuil de service, Texas Pneumatic – Ventilateur pneumatique.", "en": "For 40 years, Produits Miniers Wilson has distributed high-quality products to customers worldwide. Our products: Versa Matic — diaphragm pumps; Ictus — cement pumps; PHQ — 250 and S36 drills; Bex — Amex loaders; Ingersoll Rand — service winches; Texas Pneumatic — pneumatic fans."}, "logo": "assets/logos/exposant-67.png", "website": "https://wilson-mining.com/", "id": "exposant-67"}, {"name": "Produits sanitaires Norfil", "description": {"fr": "Depuis sa fondation en 1971, Norfil Inc. A toujours privilégie l’utilisation des nouvelles technologies au service de l’hygiène et de l’environnement. Notre conscience écologique pour la sauvegarde de notre planète est présente dans toute l’organisation. Notre expertise nous permet d’offrir un service professionnel de formation et de consultation, un service après-ventes inégalé ainsi qu’un service technique et de réparation des plus perfectionnés.", "en": "Since its founding in 1971, Norfil Inc. has always prioritized new technologies in the service of hygiene and the environment. Environmental awareness and protecting our planet are present throughout the organization. Our expertise allows us to offer professional training and consulting, unmatched after-sales service, and highly advanced technical and repair services."}, "logo": "assets/logos/exposant-68.png", "website": "https://norfil.ca/fr/", "id": "exposant-68"}, {"name": "Promellis", "description": {"fr": "Représentant de manufacturiers qui œuvrent dans les secteurs industriels, commerciaux, utilitaires et miniers. Notre objectif principal est de représenter les meilleurs manufacturiers de produits électriques pour tous les secteurs que nous desservons.", "en": "A manufacturers’ representative serving the industrial, commercial, utility and mining sectors. Our main objective is to represent the best electrical products manufacturers for every sector we serve."}, "logo": "assets/logos/exposant-69.jpg", "website": "https://promellis.com/", "id": "exposant-69"}, {"name": "Puits GDMC Forage", "description": {"fr": "Expertise en Forage de Puits Artésiens et Services Spécialisés –Nous proposons des solutions de forage sur mesure, incluant le forage de puits artésiens, de trous de service, ainsi que des forages spécialisés avec des diamètres allant de 6 à 12 pouces. Grâce à notre foreuse double rotation hautement performante, nous assurons une installation précise et fiable des tubages en acier. Venez nous rencontrer au salon pour découvrir comment notre expertise peut répondre à vos besoins spécifiques.", "en": "Expertise in artesian well drilling and specialized services. We offer custom drilling solutions, including artesian wells, service holes and specialized drilling with diameters ranging from 6 to 12 inches. Our high-performance dual-rotary drill ensures precise, reliable installation of steel casing. Meet us at the exhibition to discover how our expertise can meet your specific needs."}, "logo": "assets/logos/exposant-70.png", "website": "https://www.puitsgdmc.com/", "id": "exposant-70"}, {"name": "Recyclage de métaux intégré", "description": {"fr": "Recyclage de Métaux Intégré (RMI) est une entreprise unissant les forces de ses deux actionnaires dont ArcelorMittal Produits Longs Canada et Triple M Métal, deux des joueurs principaux dans le marché des métaux recyclés au Canada. Nos équipements diversifiés et machineries spécialisées assurent la réalisation de projets de démolition, de récupération, de nettoyage de site et le service de conteneur. Notre objectif est de fournir le meilleur service dans le domaine du recyclage de ferraille, avec une équipe dynamique et courtoise.", "en": "Recyclage de Métaux Intégré (RMI) brings together the strengths of its two shareholders, ArcelorMittal Long Products Canada and Triple M Metal, two major players in Canada’s recycled-metals market. Our diverse equipment and specialized machinery support demolition, recovery and site-cleanup projects, as well as container service. Our objective is to provide the best scrap-metal recycling service with a dynamic, courteous team."}, "logo": "assets/logos/exposant-71.png", "website": "https://rmi-imr.com/", "id": "exposant-71"}, {"name": "Rematech div.Bremo inc.", "description": {"fr": "Rematech Bremo célèbre ses 60 ans en 2025. L’entreprise possède des installations à Amos, Québec, Montréal, Saguenay, Sept-Îles et Roberval. Rematech Bremo est le distributeur officiel de la courroie de convoyeur Continental au Québec. L’entreprise possède une expertise hors pair dans le domaine de la courroie et offre les services d’installation et de réparation de courroies de convoyeur. Les techniciens en vulcanisation de Rematech Bremo sont formés et rencontrent les exigences et les normes en santé/sécurité les plus strictes. Rematech Bremo est aussi distributeur de caoutchoucs en feuille et se spécialise dans la vulcanisation de caoutchoucs de tous genres, en atelier ou en chantier, pour tous les types de poulies de convoyeur, tuyauterie, réservoirs et de chaudronnerie. Rematech Bremo est aussi distributeur autorisé des caoutchoucs de haute performance Rema Tip Top ainsi que des produits Flexco (joint mécanique, nettoyeur de courroie, système d’alignement de courroie). Également, Rematech Bremo fabrique des pièces de polyuréthanne sur demande, selon les devis et les exigences du client.", "en": "Rematech Bremo celebrates its 60th anniversary in 2025. The company has facilities in Amos, Québec City, Montréal, Saguenay, Sept-Îles and Roberval. Rematech Bremo is the official distributor of Continental conveyor belts in Québec. It offers outstanding belt expertise, as well as conveyor-belt installation and repair. Its vulcanization technicians are trained to meet the strictest health and safety requirements and standards. Rematech Bremo also distributes rubber sheeting and specializes in vulcanizing all types of rubber, in the shop or on site, for conveyor pulleys, piping, tanks and fabricated vessels. It is an authorized distributor of Rema Tip Top high-performance rubber and Flexco products, including mechanical splices, belt cleaners and belt-tracking systems. Rematech Bremo also manufactures polyurethane parts on request to customers’ specifications and requirements."}, "logo": "assets/logos/exposant-72.png", "website": "https://www.rematechbremo.com/", "id": "exposant-72"}, {"name": "Réusitech", "description": {"fr": "Réusitech excelle en tant que spécialistes dans la vente et la réparation d’alternateurs et de démarreurs, avec un focus particulier sur les systèmes électriques de service intense pour les véhicules, notamment pour l’équipement lourd, commercial et industriel. Nous sommes votre partenaire de confiance pour maintenir vos machines en parfait état de fonctionnement. Faites confiance à Réusitech pour assurer la productivité et la rentabilité de votre entreprise grâce à un service exceptionnel et des produits de haute qualité.", "en": "Réusitech specializes in selling and repairing alternators and starters, with a particular focus on heavy-duty vehicle electrical systems, including heavy, commercial and industrial equipment. We are your trusted partner in keeping your machines in perfect working order. Rely on Réusitech to support your business’s productivity and profitability through exceptional service and high-quality products."}, "logo": "assets/logos/exposant-73.png", "website": "https://www.reusitech.com/", "id": "exposant-73"}, {"name": "Richwood", "description": {"fr": "Description à venir.", "en": "Description coming soon."}, "logo": "assets/logos/exposant-74.png", "website": "https://www.richwood.com/", "id": "exposant-74"}, {"name": "Robitaille Équipement - Mori 7 inc.", "description": {"fr": "Commerce de vente d'équiments d'attachements pour machineries lourdes.", "en": "A business selling attachments and equipment for heavy machinery."}, "logo": "assets/logos/exposant-75.png", "website": "https://www.equipementrobitaille.com/mori7/", "id": "exposant-75"}, {"name": "Rockfalls Mining", "description": {"fr": "Cumulant plus de 19 ans d'expérience en matière d'exploitation minière, je suis très fier d'avoir participé à la création de Rockfall Mining: une entreprise innovante et dynamique axée sur la santé, le bien-être ainsi que la collaboration entre nous, nos différents partenaires commerciaux et nos précieux clients. Chez Rockfalls, nous nous efforçons de travailler conjointement avec nos usines de production afin de créer des outils sécuritaires et de qualité qui sauront maintenir des standards de satisfaction élevés.", "en": "With more than 19 years of mining experience, I am very proud to have helped create Rockfall Mining: an innovative, dynamic company focused on health, well-being and collaboration among ourselves, our business partners and our valued customers. At Rockfalls, we strive to work jointly with our production facilities to create safe, high-quality tools that maintain high standards of customer satisfaction."}, "logo": "assets/logos/exposant-76.png", "website": "https://www.linkedin.com/in/mike-metellus-%E2%9B%8F-367a2b25a/?isSelfProfile=false", "id": "exposant-76"}, {"name": "Rosta inc.", "description": {"fr": "Grâce à une idée de produit innovante, ROSTA est le premier fabricant mondial de systèmes à ressorts et d'amortissement en caoutchouc. Depuis 1944, notre approche cohérente centrée sur le client est une priorité absolue et contribue de manière significative au succès durable de l'entreprise. Nos composants ne nécessitent aucun entretien, sont silencieux, ont une longue durée de vie et sont utilisés pour une large gamme d'applications. De nombreuses années d'expérience en recherche et développement dans notre propre laboratoire et la collaboration avec nos partenaires et nos clients constituent une importante base de connaissances à partir de laquelle nous pouvons continuer à proposer des solutions innovantes ».", "en": "Built on an innovative product idea, ROSTA is the world’s leading manufacturer of rubber spring and damping systems. Since 1944, our consistent, customer-centred approach has been a top priority and a significant contributor to the company’s lasting success. Our components are maintenance-free, quiet and long-lasting, and are used in a wide range of applications. Many years of research and development in our own laboratory, together with collaboration with partners and customers, form an extensive knowledge base that allows us to continue offering innovative solutions."}, "logo": "assets/logos/exposant-77.png", "website": "https://rosta.com/fr/", "id": "exposant-77"}, {"name": "Sandvik", "description": {"fr": "Sandvik est un groupe mondial d'ingénierie de haute technologie, offrant des solutions qui améliorent la productivité, la rentabilité et la durabilité dans les secteurs de la production, de l'exploitation minière et des infrastructures. En tant que leader mondial, nous fournissons des équipements, des outils, des pièces, des services et des solutions techniques pour les industries minières et de la construction, avec des applications couvrant le forage, l’abattage, le chargement, le transport, le creusement de tunnels et l’exploitation en carrière. Nous mettons l’accent sur l’innovation et la transition numérique afin de générer de la valeur, d'améliorer l’efficacité opérationnelle, d’assurer la sécurité en toutes circonstances et d’optimiser l’utilisation des ressources. Pour en savoir plus : https://www.home.sandvik/en/", "en": "Sandvik is a global high-technology engineering group offering solutions that improve productivity, profitability and sustainability in manufacturing, mining and infrastructure. As a global leader, we provide equipment, tools, parts, services and technical solutions for mining and construction, with applications covering drilling, rock cutting, loading, hauling, tunnelling and quarrying. We focus on innovation and digital transformation to create value, improve operational efficiency, ensure safety in all circumstances and optimize resource use. For more information: https://www.home.sandvik/en/"}, "logo": "assets/logos/exposant-78.png", "website": "https://www.rocktechnology.sandvik/en/", "id": "exposant-78"}, {"name": "Service MSP", "description": {"fr": "Entreprise autochtone fièrement enracinée dans son territoire, nous sommes les partenaires incontournables des industries mécanique et minière. Grâce à notre service de location de personnel qualifié, nous assurons expertise et efficacité sur le terrain. Nous sommes également spécialisés dans l’installation de systèmes de graissage automatique, une solution essentielle pour prolonger la durée de vie des équipements et optimiser leur performance. Animés par un profond respect des valeurs autochtones et une approche axée sur l’innovation, nous offrons des services fiables, adaptés aux besoins spécifiques de chaque client, contribuant ainsi à la croissance durable des industries que nous desservons.", "en": "An Indigenous-owned company proudly rooted in its territory, we are a key partner to the mechanical and mining industries. Our skilled personnel rental service delivers expertise and efficiency in the field. We also specialize in installing automatic lubrication systems, an essential solution for extending equipment life and optimizing performance. Guided by deep respect for Indigenous values and an innovation-focused approach, we offer reliable services tailored to each customer’s specific needs, contributing to the sustainable growth of the industries we serve."}, "logo": "assets/logos/exposant-79.jpg", "website": "https://www.servicesmsp.ca/fr", "id": "exposant-79"}, {"name": "SEW EURODRIVE", "description": {"fr": "SEW-EURODRIVE est un leader mondial en solutions d’automatisation industrielle. SEW est un fabricant de systèmes intégrés de transmission de puissance et de contrôle de mouvement. L'excellence en ingénierie et la réactivité client définissent SEW-EURODRIVE. Nous offrons la gamme de produits la plus large du secteur, incluant des motoréducteurs, des solutions pour industrie lourde et des systèmes d'automatisation complets.", "en": "SEW-EURODRIVE is a global leader in industrial automation solutions. SEW manufactures integrated power-transmission and motion-control systems. Engineering excellence and responsiveness to customers define SEW-EURODRIVE. We offer the industry’s broadest product range, including gearmotors, heavy-industry solutions and complete automation systems."}, "logo": "assets/logos/exposant-80.png", "website": "https://sewcan.ca/fr/", "id": "exposant-80"}, {"name": "Socace", "description": {"fr": "Est un fabricant de cribles, d'alimentateur et de « grizzly » (selon un procédé unique) conçus pour les mines et les contracteurs selon nos procédés brevetés. Socace est aussi distributeur de pièces d'usure et de réparation pour ces mêmes équipements ainsi que pour les équipements de concassage tel concasseur à mâchoire, cônes, giratoires ou impacteurs, toutes marques confondues. Nous offrons également les services techniques de réparation et modification afin de permettre l'optimisation de systèmes existants.", "en": "A manufacturer of screens, feeders and grizzlies, designed through our unique, patented processes for mines and contractors. Socace also distributes wear and replacement parts for this equipment and for crushing equipment, including jaw, cone, gyratory and impact crushers of all brands. We also provide technical repair and modification services to optimize existing systems."}, "logo": "assets/logos/exposant-81.png", "website": "http://www.socace.com/index_fr.html", "id": "exposant-81"}, {"name": "Solution envisécure", "description": {"fr": "Solution Envisecure se spécialise dans le contrôle des émissions de poussière et dans le dépoussiérage industriel de toutes sortes. Nous offrons une large gamme de dépoussiéreur fabriqué sur mesure ainsi que les différentes composantes qui s’y rattaches. Que ce soit pour des cartouches ou de sac de filtration ou pour tout autres différentes composantes pour tout type de dépoussiéreur. Également nous offrons un service d’accompagnement aux entreprises comme l’inspection des équipements, l’amélioration des infrastructures, la résolution de problèmes ainsi que la réparation de machinerie.", "en": "Solution Envisecure specializes in controlling dust emissions and all types of industrial dust collection. We offer a broad range of custom-built dust collectors and their associated components, including filter cartridges, filter bags and other components for all types of collectors. We also support businesses through equipment inspections, infrastructure improvements, troubleshooting and machinery repairs."}, "logo": "assets/logos/exposant-82.jpg", "website": "https://envisecure.ca/", "id": "exposant-82"}, {"name": "Technosub", "description": {"fr": "Fondée en 1983, Technosub a pour mission de créer, fabriquer et distribuer pour les secteurs industriels et miniers, des solutions de pompage et de gestion des eaux sur mesure, innovantes et durables, dans les délais les plus courts. Avec son équipe exceptionnelle de plus de 200 professionnels dédiés et engagés, Technosub choisit de créer les conditions favorables à l’émergence d’idées innovantes ayant pour objectif la collaboration et le partenariat durable, créateur de valeur.", "en": "Founded in 1983, Technosub’s mission is to create, manufacture and distribute custom, innovative and sustainable pumping and water-management solutions for industrial and mining customers with the shortest possible lead times. With an exceptional team of more than 200 dedicated, committed professionals, Technosub creates conditions that encourage innovative ideas centred on collaboration and lasting, value-creating partnerships."}, "logo": "assets/logos/exposant-83.png", "website": "https://www.technosub.net/", "id": "exposant-83"}, {"name": "Time", "description": {"fr": "Depuis plus de 50 ans, TIME (Temiskaming Industrial Mining Equipment) fournit aux mines, à l’exploration et à l’industrie lourde une solution à source unique. Nous sommes connus pour fabriquer des produits de qualité, des réseaux d’approvisionnement efficaces et avoir un personnel expérimenté et compétent qui offre un service à la clientèle exceptionnel.Tout commence avec notre personnel, et notre approche unifiée de la conduite des affaires à l’interne et à l’externe. Nous partageons des valeurs et des objectifs communs, et comprenons l’importance de faire partie d’une équipe qui comprend nos clients. Bien que notre opération aux multiples facettes soit de nature diversifiée, c’est notre capacité à établir des relations durables avec nos clients et fournisseurs qui est unique et mémorable, et fait preuve de notre engagement envers eux.", "en": "For more than 50 years, TIME (Temiskaming Industrial Mining Equipment) has provided mining, exploration and heavy industry with a single-source solution. We are known for manufacturing quality products, maintaining efficient supply networks and having experienced, knowledgeable staff who deliver exceptional customer service. It all starts with our people and our unified approach to doing business, internally and externally. We share common values and goals and understand the importance of belonging to a team that understands our customers. Although our multifaceted operation is diverse, our ability to build lasting relationships with customers and suppliers is distinctive and memorable, demonstrating our commitment to them."}, "logo": "assets/logos/exposant-84.png", "website": "https://timeltd.ca/", "id": "exposant-84"}, {"name": "Topring", "description": {"fr": "Entreprise Canadienne. Depuis plus de 45 ans, nous mettons notre expertise en air comprimé au service des entreprises du secteur manufacturier, de l’automobile et de la construction. Grâce à nos produits et conseils, nous aidons les entreprises à améliorer leur productivité, à diminuer les risques d’accident et à réaliser des économies d’énergie. Notre mission : Rendre l’air comprimé plus accessible à travers une expérience exceptionnelle. Notre offre couvre tous les aspects d’un réseau d’air comprimé : traitement de l’air, transport des fluides, connexion aux équipements pneumatiques, régularisation de l’air et automatisation des procédés. Nos produits répondent aux normes de qualité, de sécurité et aux besoins spécifiques de chaque industrie", "en": "A Canadian company. For more than 45 years, we have put our compressed-air expertise to work for businesses in manufacturing, automotive and construction. Through our products and advice, we help businesses improve productivity, reduce accident risks and save energy. Our mission: make compressed air more accessible through an exceptional experience. Our offering covers every aspect of a compressed-air network: air treatment, fluid transport, connections to pneumatic equipment, air regulation and process automation. Our products meet quality and safety standards and the specific needs of each industry."}, "logo": "assets/logos/exposant-85.png", "website": "https://www.topring.com/fr", "id": "exposant-85"}, {"name": "Traction", "description": {"fr": "Traction chef de file Canadien dans l' après marché des pièces pour véhicules lourds . Traction est spécialisé dans la vente de pièces de véhicules lourds , MINIER, FORESTIER et CAMIONS, REMORQUES . Nous sommes aussi spécialisé dans la vente d'outillages, équipements industriels , produits chimiques, huiles et lubrifiants, produits de sécurités , produits éclairage pour équipements mobile et fixe et plus encore.5 magasin en Abitibi et plus de 100 magasins au Canada.", "en": "Traction is a Canadian leader in aftermarket heavy-vehicle parts. It specializes in selling parts for heavy vehicles, mining and forestry equipment, trucks and trailers. We also sell tools, industrial equipment, chemicals, oils and lubricants, safety products, lighting products for mobile and stationary equipment, and more. Five stores in Abitibi and more than 100 stores across Canada."}, "logo": "assets/logos/exposant-86.png", "website": "https://www.traction.com/", "id": "exposant-86"}, {"name": "Trelec", "description": {"fr": "Nous sommes l'agent manufacturier pour plusieurs entreprises du domaine de la protection et automatisation de systèmes électriques comme GEPR ENERGY (Multilin), MELTRIC, MegAlert, HAWK MEASUREMENT, DENCO FUSES et LEX. Nous sommes basés à St-Augustin de Desmaures, Québec, Canada.", "en": "We are the manufacturers’ representative for several companies in electrical system protection and automation, including GEPR ENERGY (Multilin), MELTRIC, MegAlert, HAWK MEASUREMENT, DENCO FUSES and LEX. We are based in Saint-Augustin-de-Desmaures, Québec, Canada."}, "logo": "assets/logos/exposant-87.png", "website": "https://trelec.ca/", "id": "exposant-87"}, {"name": "Trionex", "description": {"fr": "Est une entreprise spécialisée dans le domaine de l'hydraulique, du pneumatique et de l'électromécanique. Depuis plus de 40 ans, nous desservons les marchés de l'Abitibi-Témiscamingue, du Québec et de l'Ontario, dans la fourniture et réparation de cylindres, pompes, moteurs, valves & autres composantes. Nous œuvrons depuis longtemps dans les domaines miniers et forestiers, qui sont en constante évolution et dans lesquels nous nous sommes forgés une expérience inégalée au fil des ans. Notre priorité sera toujours de fournir un service de qualité, même en urgence!", "en": "A company specializing in hydraulics, pneumatics and electromechanics. For more than 40 years, we have served Abitibi-Témiscamingue, Québec and Ontario, supplying and repairing cylinders, pumps, motors, valves and other components. We have long worked in the constantly evolving mining and forestry industries, building unmatched experience over the years. Providing quality service will always be our priority, even in emergencies!"}, "logo": "assets/logos/exposant-88.png", "website": "https://www.trionex.ca/fr/index.cfm", "id": "exposant-88"}, {"name": "Uni-Drill", "description": {"fr": "Uni-Drill, basé à Val-d’Or, est un manufacturier d’équipements de forage d’exploration et de définition, tant souterrains que de surface. Ses systèmes fixes ou mobiles offrent des solutions innovantes pour optimiser l’efficacité opérationnelle. Grâce à son expertise technique et à son équipe spécialisée, Uni-Drill assure des résultats précis, rapides et sécuritaires.", "en": "Based in Val-d’Or, Uni-Drill manufactures exploration and definition drilling equipment for both underground and surface use. Its stationary and mobile systems provide innovative solutions to optimize operational efficiency. Through its technical expertise and specialized team, Uni-Drill delivers precise, fast and safe results."}, "logo": "assets/logos/exposant-89.jpg", "website": "https://www.uni-drill.com/en-ca", "id": "exposant-89"}, {"name": "Viacore", "description": {"fr": "Viacore Solutions est un leader de confiance dans la manutention des matériaux, offrant depuis plus de 50 ans des courroies de convoyeur de haute qualité, des accessoires et un service expert à travers l'Amérique du Nord. Nous soutenons l'industrie minière et de nombreux autres secteurs avec des solutions innovantes conçues pour maximiser la disponibilité et l’efficacité des opérations. Nos courroies de convoyeur robustes sont conçues pour résister aux conditions les plus exigeantes, et notre équipe de services mécaniques assure l’installation experte, la jonction de courroie, le revêtement de poulies, la conception de chute, le contrôle des émissions de poussière, et bien plus encore. Grâce à une technologie de pointe, des solutions à valeur ajoutée éprouvées et un service d’urgence 24/7, Viacore garantit la fiabilité, l’efficacité et la continuité de vos opérations.", "en": "Viacore Solutions is a trusted leader in material handling, providing high-quality conveyor belts, accessories and expert service throughout North America for more than 50 years. We support mining and many other industries with innovative solutions designed to maximize operational uptime and efficiency. Our rugged conveyor belts withstand the most demanding conditions, and our mechanical services team provides expert installation, belt splicing, pulley lagging, chute design, dust-emission control and much more. With advanced technology, proven value-added solutions and 24/7 emergency service, Viacore ensures the reliability, efficiency and continuity of your operations."}, "logo": "assets/logos/exposant-90.jpg", "website": "https://viacore.com/", "id": "exposant-90"}, {"name": "Vibro tech", "description": {"fr": "Vibrotech est une entreprise manufacturière œuvrant depuis près de 30 ans dans la conception, la fabrication et l’installation d’équipement industriel. Nous excellons dans la conception de solutions clés en main pour la manutention de vrac, avec ou sans technologie vibrante, et fabriquons des équipements durables et performants tel que des convoyeurs, silos, trémies, tamis, alimentateurs vibrants, etc. Notre approche d’ingénierie globale va bien au-delà de la simple fabrication d’équipements. Nous concevons et mettons en place des lignes de production complètes, avec un objectif clair : offrir une solution intégrée qui répond parfaitement aux besoins uniques de chaque client. L’équipe de Vibrotech sera toujours honorée de vous compter parmi sa clientèle, que vous soyez situé au Québec, en Ontario, dans les Maritimes, aux États-Unis où partout ailleurs en Amérique du Nord. Soyez assurés que l’équipe de Vibrotech travaillera toujours à la mesure de vos exigences afin de faire de vos projets une réussite pour votre entreprise.", "en": "Vibrotech has worked for nearly 30 years in the design, manufacture and installation of industrial equipment. We excel in designing turnkey bulk-material handling solutions, with or without vibratory technology, and manufacture durable, high-performance equipment such as conveyors, silos, hoppers, screens and vibrating feeders. Our comprehensive engineering approach goes far beyond equipment manufacturing. We design and install complete production lines with a clear objective: delivering an integrated solution that meets each customer’s unique needs. The Vibrotech team is always honoured to serve you, whether you are in Québec, Ontario, the Maritimes, the United States or elsewhere in North America. You can be confident that we will work to meet your requirements and make your projects successful for your business."}, "logo": "assets/logos/exposant-91.png", "website": "https://www.vibrotech.ca/fr/", "id": "exposant-91"}, {"name": "Victaulic", "description": {"fr": "Depuis 1919, les solutions d'assemblage mécanique et de contrôle du débit des tuyauteries de Victaulic ont permis d'accroître la productivité et de réduire les risques relatifs à la construction, faisant en sorte que les projets soient achevés en toute sécurité, dans les délais exigés et en respectant le budget autorisé. Poussé par un esprit d'innovation continue, le portefeuille de plus de 100 000 produits et technologies brevetées de Victaulic favorise la liberté de conception et facilite l’inspection et la maintenance pendant la durée de vie complète de tous les systèmes.Avec plus de 3 500 employés et 40 bureaux dans le monde entier, Victaulic aide des clients dans plus de 120 pays à réussir au sein de l'industrie mondiale de la construction. Des plus hauts édifices aux mines les plus profondes, nos clients font confiance à nos produits pour augmenter la durabilité générale du système dans le cadre de projets de construction exigeants et de conditions de fonctionnement extrêmement difficiles. Pour plus d’informations sur la façon dont nos produits de tuyauterie innovants et nos services de conception peuvent donner vie à vos projets de construction, rendez-vous sur www.victaulic.com.", "en": "Since 1919, Victaulic’s mechanical pipe-joining and flow-control solutions have increased productivity and reduced construction risks, helping projects finish safely, on time and within budget. Driven by continuous innovation, Victaulic’s portfolio of more than 100,000 products and patented technologies supports design freedom and simplifies inspection and maintenance throughout the life of piping systems. With more than 3,500 employees and 40 offices worldwide, Victaulic helps customers in over 120 countries succeed in the global construction industry. From the tallest buildings to the deepest mines, customers trust our products to improve overall system durability in demanding construction projects and extremely difficult operating conditions. To learn how our innovative piping products and design services can bring your construction projects to life, visit www.victaulic.com."}, "logo": "assets/logos/exposant-92.png", "website": "https://fr.victaulic.com/?_gl=1*11qy48i*_gcl_aw*R0NMLjE3NDEyNzcyNzQuQ2p3S0NBaUFyS1ctQmhBekVpd0FaaFdzSUpvV2xWUlJud3p3c1A0N1czQzBOVUg3b25sek94RzdVMW8wWTRIZk1VRXJHdzNpcWtqdTRCb0NnSTBRQXZEX0J3RQ..*_gcl_au*MTc0OTE2NzkxMS4xNzQxMjc3MjI3*_ga*MTEzMTQ4MjY4NC4xNzQxMjc3MjI3*_ga_DX3N6GLST2*MTc0MTI3NzIyNy4xLjEuMTc0MTI3NzI4MS4wLjAuMA..*_ga_W9Y963LKFY*MTc0MTI3NzIyNy4xLjEuMTc0MTI3NzI3My4wLjAuMA..", "id": "exposant-92"}, {"name": "Ville de Malartic", "description": {"fr": "Plan de développement durable et programme de soutien.", "en": "Sustainable development plan and support program."}, "logo": "assets/logos/exposant-93.png", "website": "https://malartic.quebec/", "id": "exposant-93"}, {"name": "Wago", "description": {"fr": "Des solutions pour un succès commun. Technologie de connexion, technologie d'automatisation, électronique d'interface : depuis plus de 60 ans, nous combinons l'ingénierie et l'innovation et, en tant que partenaire fiable, nous renforçons nos clients dans tous leurs défis. Le résultat est de nouveaux produits et des solutions globales sur lesquelles tout le monde peut compter.", "en": "Solutions for shared success. Connection technology, automation technology and interface electronics: for more than 60 years, we have combined engineering and innovation and, as a reliable partner, supported our customers through every challenge. The result is new products and comprehensive solutions everyone can depend on."}, "logo": "assets/logos/exposant-94.png", "website": "http://www.wago.ca/", "id": "exposant-94"}, {"name": "Wajax", "description": {"fr": "Un chef de file de l’industrie canadienne, Wajax est au service des plus grandes industries canadiennes depuis 1858 en tant que l’un des principaux fournisseurs de produits et de service industriels au pays. Grâce à notre vaste gamme de produits et de services, nous répondons aux besoin de tous les principaux secteurs de marché : exploitation minière , solution d’entreposage, construction, foresterie, sable bitumineux, marine, secteur alimentaire. Avec nos plus de 100 succursales, les 19 centres de réparations, nos centres d’ingénieries et avec notre force de ventes . Ensemble, nous en faisons plus!", "en": "A Canadian industry leader, Wajax has served Canada’s largest industries since 1858 as one of the country’s leading providers of industrial products and services. Our extensive offering meets the needs of major market sectors: mining, warehousing solutions, construction, forestry, oil sands, marine and food. We support customers through more than 100 branches, 19 repair centres, engineering centres and our sales force. Together, we do more!"}, "logo": "assets/logos/exposant-95.png", "website": "https://www.wajax.com/fr/", "id": "exposant-95"}, {"name": "Weidmuller LTD", "description": {"fr": "Weidmüller – Votre Partenaire Industriel. Que ce soit pour l'alimentation électrique, la transmission de signaux, la gestion des données ou la recherche de solutions intégrées. Le groupe Weidmüller est votre partenaire mondial pour la transformation numérique. Son objectif est de façonner l'avenir de l'industrie grâce à des produits, des solutions et des services adaptés à la connectivité industrielle intelligente et à l'Internet Industriel des Objets (IIoT). 4418 Rue Louis-B.-Mayer Laval (Québec) H7P 0G1", "en": "Weidmüller — Your Industrial Partner. Whether for electrical power supply, signal transmission, data management or integrated solutions, the Weidmüller Group is your global partner in digital transformation. It aims to shape industry’s future through products, solutions and services for smart industrial connectivity and the Industrial Internet of Things (IIoT). 4418 Rue Louis-B.-Mayer, Laval (Québec) H7P 0G1"}, "logo": "assets/logos/exposant-96.png", "website": "https://www.weidmuller.ca/en/index.jsp", "id": "exposant-96"}, {"name": "Weir ESCO", "description": {"fr": "La solution d'ingénierie d'usure définit notre entreprise. Nous utilisons l'ingénierie, le bon mélange de produits et notre main-d’œuvre qualifiée pour résoudre les problèmes d'usure des clients pour des équipements plus solides et plus durables.", "en": "Wear-engineering solutions define our company. We use engineering, the right product mix and our skilled workforce to solve customers’ wear problems and deliver stronger, longer-lasting equipment."}, "logo": "assets/logos/exposant-97.png", "website": "https://www.esco.weir/", "id": "exposant-97"}, {"name": "Westburne", "description": {"fr": "Une division de Rexel Canada Électrique inc., distributeur de matériel électrique et spécialiste de fils et câbles.", "en": "A division of Rexel Canada Electrical Inc., an electrical supplies distributor specializing in wire and cable."}, "logo": "assets/logos/exposant-98.png", "website": "https://www.westburne.ca/cwr/", "id": "exposant-98"}, {"name": "Westlund", "description": {"fr": "Westlund a une riche histoire dans l’industrie de distribution de tuyauterie, valves et raccords.Fondée à Edmonton en 1963, Westlund a été acquise par EMCO Corporation en 1986. Forts d’une solide réputation, nous servons nos clients dans plus de 28 centres Westlund dévoués à travers le Canada et nous tirons profit d’un réseau de plus de 300 centres de distribution EMCO à travers le Canada.Ses membres sont des experts dans leur champ d’activités, sont des innovateurs dans la résolution de problèmes et sont des avant-gardistes avec un sens aigu de la réussite de leur objectif : tout faire pour que vos projets soient un succès.", "en": "Westlund has a rich history in pipe, valve and fitting distribution. Founded in Edmonton in 1963, Westlund was acquired by EMCO Corporation in 1986. With a strong reputation, we serve customers through more than 28 dedicated Westlund centres across Canada and draw on a network of over 300 EMCO distribution centres nationwide. Our people are experts in their fields, innovative problem-solvers and forward-thinkers with a clear goal: doing everything possible to make your projects successful."}, "logo": "assets/logos/exposant-99.png", "website": "https://westlundpvf.com/", "id": "exposant-99"}, {"name": "Wolseley", "description": {"fr": "Le plus grand distributeur au Québec à vous en offrir autant! Pour les professionnels en aqueduc, chauffage, climatisation, industriel, mines, plomberie, PVF, protection des incendies, outillage, ventilation. Un réseau de 38 succursales spécialisées. Des équipes dédiées de spécialistes, dans votre domaine d’activité. Un service d’estimation efficace et professionnel. Des produits toujours disponibles en succursales, à nos entrepôts régionaux ou au centre de distribution, livrés juste à temps! « Plus de choix, plus de compétence, plus de service. » Les grandes marques et produits : Triangle Fluid, MA Stewart, Milwaukee, Canun, Victaulic…", "en": "Québec’s largest distributor offering so much! For professionals in waterworks, heating, air conditioning, industry, mining, plumbing, PVF, fire protection, tools and ventilation. A network of 38 specialized branches, with dedicated teams of specialists in your field. Efficient, professional estimating service. Products always available at branches, regional warehouses or the distribution centre, delivered just in time! ‘More choice, more expertise, more service.’ Major brands and products include Triangle Fluid, MA Stewart, Milwaukee, Canun and Victaulic."}, "logo": "assets/logos/exposant-100.png", "website": "https://www.wolseleyexpress.com/en/", "id": "exposant-100"}];
